	title 'QD Text              GS ROM 3.0'*****************************************************************			   **              TEXT			   **			   *** Modification History** pre Jan 89	Bennet and Steve did a whole buncha stuff!** 2/20/89	Mensch** First FastFont stuff done. Modified almost all the routines at least* a little.* * 2/24/89	Mensch** Fixed bugs in fastfont clipping and drawing. CalcGood drawstatus* now returns a little more info!*** 12 Mar 89	Steven Glass** Changed MakeFastFontInfo called by JSL instead of JSR so * can be used easily in patch file.** 4/7/89	Mensch* Made fastfont routines add spExtra and chExtra when calculating the* width of a character. NOTE: the routine now uses a new zpage value* called fastbucket, which is aliased over a variable used to apply styling.** 4/10/89	Mensch** God, how I hate mondays! Fixed a really stupid bug in fastfonts that* caused 2 pixels to be added when spextra only indicated 1. Geez, I am* a total spaz, I am so embarassed that I screwed up the build that I will leave* this comment like this for future programmers to see my shame!** 4/24/89	Mensch* Fixed yet another bug with mono-spacing. That feature is dangerous and should * be removed (especially since it is only used by bone headed programmers!** 27-Nov-91	Dave Lyons** Changed InflateTextBuffer to return errors it gets while resizing* the text buffers (including QD Aux's buffers).** 3-Dec-91	Dave Lyons** Finished fixing above--on failure, it needs to restore a few direct page* locations, so we don't think the buffer has been inflated when it hasn't.* (Since QuickDraw Aux chains in *after* the main QD buffer-resize routines,* QD already decided it was okay to store the new buffer size values when* QD Aux found it could not resize its buffers, so we have to undo the damage.)**********************************************************************************************************************************			   **	Copyright (C) 1985-1989,1991	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	blanks off	string asis	include 'all.macros'			macro	macswitch	mend	MACRO&lab	IncLong &adr&lab	inc &adr	bne @1	inc &adr+2@1	mend				include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:TextEquates'	INCLUDE ':QDEquates:fontequs';------------------------------------------;; Equates from procedure iSetUpFontInfo;;------------------------------------------fbrExtent	equ fRectMax;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC	IMPORT BusyEC0	IMPORT BusyEC10	IMPORT BusyEC2	IMPORT BusyEC4	IMPORT BusyEC6	IMPORT BusyEC8	IMPORT ConTable320	IMPORT ConTable640	IMPORT ExtendColorWord	IMPORT QDStart	IMPORT ShiftOut	IMPORT ShiftStay	IMPORT SystemFont	IMPORT TestGPs	IMPORT leftBitMask	IMPORT rightBitMask;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CallText	ENTRY CallTxBounds	ENTRY CallWidth	ENTRY FastBigLoop	ENTRY GetFL	ENTRY GetRFRec	ENTRY InflateTB	ENTRY SlowBigLoop	ENTRY StuffBig0320	ENTRY StuffBig0640	ENTRY StuffBig1320	ENTRY StuffBig1640	ENTRY StuffBig2320	ENTRY StuffBig2640	ENTRY StuffBig3320	ENTRY StuffBig3640	ENTRY StuffBig4320	ENTRY StuffBig4640	ENTRY StuffBig5320	ENTRY StuffBig5640	ENTRY StuffBig6320	ENTRY StuffBig6640	ENTRY StuffBig7320	ENTRY StuffBig7640	ENTRY WCString	ENTRY WChar	ENTRY WText	ENTRY iBCString	ENTRY iBChar	ENTRY iBText	ENTRY iDCString	ENTRY iDChar	ENTRY iDText;;                copy text/TextWidthCalls****************************************************************** CharWidth*              Char	    word (input)*              Width    word (output)******************************************************************	EXPORT CharWidthCharWidth	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3theChar	equ RTL2+3resultWidth	equ theChar+2	jsr QDStart	lda TheChar,s	and #$00FF	; added 2/10/89 mensch	sta charToDraw	; Hey bennet make this right	lda #DrawCharVerb	jsl CallWidth	lda TheWidth	sta ResultWidth,s	jmp BusyEC2	ENDP****************************************************************** StringWidth*              StringPtr     long (input)*              Width         word (output)           *****************************************************************	EXPORT StringWidthStringWidth	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3StrPtr	equ RTL2+3resultWidth	equ StrPtr+4	jsr QDStart* Make this look just like DrawText	lda StrPtr,s	; bennet will make these use	sta TextPtr	; the right names	lda StrPtr+2,s	sta TextPtr+2	lda [TextPtr]	and #lowByte	sta TextLength	IncLong TextPtr	lda #DrawTextVerb	jsl CallWidth	lda theWidth	sta resultWidth,s	jmp BusyEC4	ENDP****************************************************************** TextWidth*              PtrToText : long (input)*              TextLength : word (input)*              Width:  word (output)******************************************************************	EXPORT TextWidthTextWidth	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheTextLength	equ RTL2+3TheTextPtr	equ TheTextLength+2resultWidth	equ theTextPtr+4	jsr QDStart	lda TheTextPtr,s	sta TextPtr	lda TheTextPtr+2,s	sta TextPtr+2	lda TheTextLength,s	sta TextLength	lda #DrawTextVerb	jsl CallWidth	lda theWidth	sta resultWidth,s	jmp BusyEC6	ENDP****************************************************************** CStringWidth*              CStrPtr : long (input)*              Width:  word (output)******************************************************************	EXPORT CStringWidthCStringWidth	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3CStrPtr	equ RTL2+3resultWidth	equ CStrPtr+4	jsr QDStart	lda CStrPtr,s	sta TextPtr	lda CStrPtr+2,s	sta TextPtr+2	lda #DrawCStrVerb	jsl CallWidth	lda theWidth	sta resultWidth,s	jmp BusyEC4	ENDP****************************************************************** CallWidth** This routine called by the entry points standard* text inputs are on zero page.** Zero page is already switched in by the time it gets here.*****************************************************************	EXPORT CallWidthCallWidth	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	sta DrawVerb	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdTxMeasUseLocal	phb	; put extra byte on	stack	ldy #o_stdTxMeas	; get adr of new text width routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** StdTxMeas** Common text measuring routine that is	central point for* all text measuring routines.** When control gets	here, all inputs are on zero page.** There are lots of	possiblities as to what they are.  And the* Draw verb is what	tells us what to do.**       For CharWidth*               char is on zp at charToDraw**       For TextWidth*               pointer is on zp*               length is on zp**       For CStringWidth*               pointer is on zp*****************************************************************	EXPORT iStdTxMeasiStdTxMeas	PROC;soon to be iStdTxMeas*              using CoreDATA*              using PicInfo*              using QDProcs	lda DrawVerb	; put verb in a	asl a	tax	jmp (DoWidthTable,x)DoWidthTable		; 	DC.W WChar	DC.W WText	DC.W WCString	ENDP****************************************************************** WChar*****************************************************************	EXPORT WCharWChar	PROC*              USING E0Vectors*              USING CoreData;	lda #0	; use old font info	jsl SetUpFontInfo	jsl ValidChar	and #lowByte	sta theWidth;;	rtl	ENDP****************************************************************** WText******************************************************************	EXPORT WTextWText	PROC	EXPORT WCStringWCString		;       *              USING E0Vectors*              USING CoreData;	stz currPen;	jsl GetNextChar	bcs NullString;	lda #0	; use old font info	jsl SetUpFontInfo	jsl BumpPen;;NullString		; 	lda currPen	sta theWidth	rtl;	ENDP;;                copy text/TextDrawCalls****************************************************************** DrawChar*              Char	    word******************************************************************	EXPORT DrawCharDrawChar	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheChar	equ RTL2+3	jsr QDStart	lda TheChar,s	sta charToDraw	lda #DrawCharVerb	jsl CallText	jmp BusyEC2	ENDP****************************************************************** DrawString*              StringPtr     long*****************************************************************	EXPORT DrawStringDrawString	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3StrPtr	equ RTL2+3	jsr QDStart	lda StrPtr,s	; bennet will make these use	sta TextPtr	; the right names	lda StrPtr+2,s	sta TextPtr+2	lda [TextPtr]	and #lowByte	sta TextLength	IncLong TextPtr	lda #DrawTextVerb	jsl CallText	jmp BusyEC4	ENDP****************************************************************** DrawText*              PtrToText : long*              TextLength : word******************************************************************	EXPORT DrawTextDrawText	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheTextLength	equ RTL2+3TheTextPtr	equ TheTextLength+2	jsr QDStart	lda TheTextPtr,s;	sta TextPtr	lda TheTextPtr+2,s	sta TextPtr+2	lda TheTextLength,s	sta TextLength	lda #DrawTextVerb	jsl CallText	jmp BusyEC6	ENDP****************************************************************** DrawCString*              CStrPtr : long******************************************************************	EXPORT DrawCStringDrawCString	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3CStrPtr	equ RTL2+3	jsr QDStart	lda CStrPtr,s	sta TextPtr	lda CStrPtr+2,s	sta TextPtr+2	lda #DrawCStrVerb	jsl CallText	jmp BusyEC4	ENDP****************************************************************** CallText** This routine called by the entry points standard* text inputs are on zero page.** Zero page is already switched in by the time it gets here.*****************************************************************	EXPORT CallTextCallText	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	sta DrawVerb	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdTextUseLocal	phb	; put extra byte on	stack	ldy #o_stdtext	; get adr of new text routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** StdText** Common text routine that is central point for* all text drawing routines.** When control gets	here, all inputs are on zero page.** There are lots of	possiblities as to what they are.  And the* Draw verb is what	tells us what to do.**       For DrawChar*               char is on zp at charToDraw**       For DrawText*               pointer is on zp*               length is on zp**       For DrawCString*               pointer is on zp*****************************************************************	EXPORT iStdTextiStdText	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	lda #TextNoun	jsl PutPictStuff	; inputs on zp and in a-reg	lda DrawVerb	; put verb in a	asl a	tax	jmp (DoTextTable,x)DoTextTable		; 	DC.W iDChar	DC.W iDText	DC.W iDCString	ENDP******************************************		**  current date and	time:	**    11:30 AM, 5/2/86	**		******************************************;********************************************************************************			                  **              subroutine DChar		                  **			                  **		started 4/2/86 or before              **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this is the framing routine which is used by DrawChar to draw a **  character into the current grafport's pixelmap.  It does everything that   **  DrawChar wants -	see external documentation.	                  **			                  **  ASSUMPTIONS:  Very few.  QD II must be active.  The character to be drawn  **  must be in charToDraw.  That kind of	thing.	                  **			                  **  RETURNS:  pnLoc.H in the current grafport is increased by the character    **  width, whether or not the character was actually drawn.	                  **			                  **  ALTERS:  most if	not all of the QD II globals may be changed by this rou-  **  tine.			                  **			                  **  NOTES:  DBR is preserved.		                  **			                  **  DChar returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 4/2/86		**    changed for style mods - 5/2/86,	**    BHM		**		******************************************;	EXPORT iDChariDChar	PROC	Import fastPutChar*              using E0Vectors*              using CoreData;	jsl PortLoc2ZP	; bring down the dest info	jsl SetUpPortRegions	lda #-1	; flag that says its ok to use fastfont info...	jsl SetUpFontInfo	ldy #(O_pnLoc+O_H)	lda [portRef],y	;pnLoc.H	sta currPen;	jsl CalcDrawStatus	;check for invis. pen or null minRect	bcc GoodDrawStatus;bad draw status:; or, bad fast character, both go here!	jsl ValidChar	and #lowByte	;get character width	clc	adc currPen	;add to current pen	ldy #(O_pnLoc+O_H)	sta [portRef],y	;and replace in grafport	bra BadDrawStatus;; This is where we fall when you have a bad fastDrawStatus;GoodDrawStatus		; ;; Modified 2/10/89; This tests for fast font routines...; first test the high bit of the font handle to see if it is set,; if it is, we will call the fast text routines!	php	bit <fontFlags	bvs @stillfast	plp	bra iDCharOldWay@StillFast	plp;	ldy #O_Font+2;	lda [<PortRef],y	; get the high word of the font handle...;	bpl iDCharOldWay	; if clear, forget this next stuff	bvc BadFastChar	; if overflow clear the regions aren't rects...	brl tryFastChar	; try drawing the character the fast way...;; This is the alternate entry to draw a character the old way!BadFastChar	lda #0	jsl SetUpFontInfo	; set up the original fonts info...; and drop right thru to the good draw routine...	Export iDCharOldWayiDCharOldWay;****  ADDED 3/10/87	TO USE USE CALCSLOP;	jsl CalcSlop;;now SetUpBufInfo can use the slop value;***  END OF CHANGE - BHM  x6245;	jsl SetUpBufInfo	jsl PutChar	lda bufPen	;final pen position, buffer coords	clc	adc hBufToLoc	;switch to local	ldy #(O_pnLoc+O_H)	sta [portRef],y;	jsl StyleText	;perform style mods, if needed;get intersection of active text buffer	and minRect:	jsl TextAndMinRect	bcs NullInt	;intersection was null;no, it wasn't:	jsl CalcTextBounds	;get parameters for	transfer	jsl BlowItUp	;transfer into destination pixelmap;NullInt		; 	jsl CleanUpBuffer;BadDrawStatus		; ;	jsl FreePortRegions	rtl;;; NEW: this is the faster drawchar routine, this routine will test to see that the; char we want to draw can be drawn into the current minrect, if not, we bag it; and do it the old way!tryFastChar; Create a character rectangle in local coordinants now...	ldy #o_PnLoc+o_V	; offset to pen loc.v	lda [<portRef],y	clc	; set to add an extra 1	adc <descent	; add the fonts descent to this value	cmp <MinRect+o_V2	; see if we are within bounds...	beq @1	bpl notWhole	; this is the bottom@1	sta <MinRect+o_V2; NOTE: this next subtract RELY's on the carry being clear from above compare!	sec	sbc <descent	; now create the top of our character rectangle	sbc <ascent	; by subtracting the character ascent and decsent	sta <charRect+o_V1	cmp <MinRect+o_V1	; see if we are too high	bmi notWhole	sta <MinRect+o_V1	lda <CurrPen	; offset to penloc.H	sta <charRect+o_H1	; make this the right edge	cmp <MinRect+o_H1	bmi NotWhole	sta <MinRect+o_H1; now get the right edge...	jsl validChar	; get the width of the character	cmp #13	; see if its too big...	blt @2	lda #12	; max char width = 12...@2	clc	sta <theWidth	; save the width of this character	adc <charRect+o_H1	cmp <MinRect+o_H2	bpl notWhole	sta <minRect+o_H2	bra goFast	; if we get this far, we can do the fast drawingnotWhole	brl badFastChar	; if not whole, just do it the old way...;; If we get this far, then we can go the fast way!goFast; we must now convert our rectangle to 'global' locinfo coordinants; we do this by first creating an 'offset' to add to our rectangle... NOTE: this now only; operates on the top left		lda <charRect+o_V1	sec	sbc <boundsRect+o_V1	sta charRect+o_V1	bmi notWhole	; if this is negative, somethings wrong..		lda <charRect+o_H1	sec	sbc <boundsRect+o_H1	sta charRect+o_H1	bmi notWhole	; if this is negative, somethings wrong..; now that I have the proper offset for the character, I will compute the characters; location in memory based on the locinfo record...;; IMPORTANT for improved drawing we must now call shield cursor!; NOTE MinRect now contains our character rectangle!	jsl ShieldCursor	; and shield the cursor now!	stz <fastLineStat	lda <width	cmp #$00A0	; special case for screen port rects	bne @doMult1	lda charRect+o_V1	; get the character rectangle top	cmp #400	; see if we rolled over the top of the mult below	bge @DoMult2	asl a	; multiply it by 32 first..	asl a	asl a	asl a	asl a	sta Mult1	asl a	asl a	clc	adc Mult1	ldx #0	bra @DoMult3@DoMult2	lda <width@DoMult1	sta Mult2	; save it for the multiply	lda charRect	; get the v1 coordinant	sta Mult1	jsr DoMultiply	; multiply these two numbers@DoMult3; once we have it this far, we can create the address of the starting scan line to ; draw upon...	adc <imageRef	; add to the base image reference	sta destRef	; save this for a second...	txa	adc <imageRef+2	; and create the high word	sta destRef+2	lda <CharRect+o_H1	; now compute the offset into destref	lsr a	; divide this by 4(pixels per byte)	lsr a	clc	; and add it in creating our final offset	adc destRef	sta destRef	bcc @1	inc destRef+2@1;; Added notes: the following is called from	export DrawOneFromaLineDrawOneFromaLine; Now bump the point to reflect the new position	lda <theWidth; DRAT big bug here, didn't have the carry clear so text was a little longer than it; should have been when using spExtra! this has been curred! (Now I clear the carry)	clc	; clear the carry, valid char no longer does this	adc <currPen	sta <currPen;; This can be called if lines calc <currpen for us...;; and now deref points to the proper scan line and create the proper shifting info	lda <CharRect+o_H1	; now compute the initial offset and shift value	and #$0003	; get the shift over value...	bne @MustShift	; see if we must do any shifting	stz <shiftInfo	; zero out shift info...; Ignore the left mask, unused...; NOTE: we also don't have to do those funky shifts that we had to do below	adc <theWidth	; add the width	and #$0007	; only need the last 3 bits	asl a	; to create the right mask...	tax	lda >rMaskTbl,x	sta <FastMaskRight; now copy the strike pointer...	lda <charToDraw	; get the character to draw	asl a	; create the table offset	adc #$0100	; add 100 since the table is offset by that much	tay	; use this as an index	lda [<fastHeadPtr],y	adc <fontStrike1	; get the low word	sta <srcRef	; and save this as our source reference	lda <fontStrike1+2	sta <srcRef+2	bcc @12	inc SrcRef+2@12;;	lda <fontStrike1	; get the low word;	sta <srcRef	; and save this as our source reference;	lda <fontStrike1+2;	sta <srcRef+2	bra @NoShiftReEntry@MustShift; If we get here we must have had to do a buncha shifting...	sta <shiftinfo	asl a	; and save it...	tax	; now use it as a table offset	lda >lMaskTbl,x	sta <fastMaskLeft	txa	lsr a	; get the shift offset back again	adc <theWidth	; add the characters width...	and #$0007	; we are only interested in the last 3 bits...	asl a	; multiply by 2 for a table offset	tax	; put x into <A>	lda >rMaskTbl,x	; and get the right mask...	sta <fastMaskRight;	lda <shiftInfo	; but first, multiply our offset by 2 again	asl a	; cuase this is a table of ptrs...	asl a	tax	lda <charToDraw	; get the character to draw	asl a	; create the table offset	adc #$0100	; add 100 since the table is offset by that much	tay	; use this as an index	lda [<fastHeadPtr],y	adc <fontStrike1,x	; get the low word	sta <srcRef	; and save this as our source reference	lda <fontStrike1+2,x	sta <srcRef+2	bcc @1	inc SrcRef+2@1;; Now finish creating our destination pointer...@NoShiftReEntry;	lda <CharRect+o_H1	; now compute the offset into destref;	lsr a	; divide this by 4(pixels per byte);	lsr a;	clc	; and add it in creating our final offset;	adc destRef;	sta destRef;	bcc @1;	inc destRef+2;@1; At this point deref now points us to the final offset in the grafport to draw our; character. Now we need to do some character stuff...; and bump our source ref to reflect the character offset...;; NOTE: with the new fast font record, we could change this!, it would become...;;	lda <charToDraw	; get the character to draw;	asl a	; create the table offset;	adc #$0100	; add 100 since the table is offset by that much;	tay	; use this as an index;	lda [<fastHeadPtr],y;	adc <srcRef	; add it to the source ref;	sta <srcRef;	bcc @100;	inc <srcRef+2;@100; We now have srcref set up to point to the character to draw, destref set up; to point to the location to start drawing it. maskright and maskleft set to; the proper masking for the edges, theWidth set to the character width and; shiftinfo set to the number of pixels *2 to shift, now with all that set we can; call fastputchar	jsr fastputChar	lda <fastLineStat	; test to see if we are drawing a fast line	bne endForLine	lda <currPen	; update currPen properly...	ldy #o_PnLoc+o_H	sta [<portRef],y	jsl UnShieldCursor	; turn the cursor back on again	brl BadDrawStatus	EndForLine	rts	Export MakeFastFontInfo	Export MakeFastFontInfo2MakeFastFontInfo	ldy #o_Font	; first load and deref the font handle	lda [<portRef],y	; get the font handle	sta <fontHeadPtr	iny	iny	lda [<portRef],y	sta <fastHeadPtr+2MakeFastFontInfo2	ldy #2	lda [<fastHeadPtr],y	tax	lda [<fastHeadPtr]	sta <fastHeadPtr	txa	ora #$8000	sta <fastHeadPtr+2	tax	lda <fastHeadPtr	; A and X now contain the pointer to our data; create the 4 font strike pointers here	clc	; now offset to the first strike...	adc #o_FFEndOfTables	bcc @1	inx	clc@1		stx <fontStrike1+2	sta <fontStrike1		ldy #o_StrikeSize	; and create the other 3 pointers...	adc [<fastHeadPtr],y	bcc @2	inx	clc@2	stx <fontStrike2+2	sta <fontStrike2	adc [<fastHeadPtr],y	bcc @3	inx	clc@3	stx <fontStrike3+2	sta <fontStrike3	adc [<fastHeadPtr],y	bcc @4	inx	clc@4	stx <fontStrike4+2	sta <fontStrike4;; Now set up the rest of the font info here so we can use it!	ldy #o_ffAscent	lda [<fastHeadPtr],y	sta <Ascent	ldy #o_ffDescent	lda [<fastHeadPtr],y	sta <descent	ldy #o_FFrowBytes	lda [<fastHeadPtr],y	sta <rowBytes	ldy #o_FFMaxWidth	lda [<fastHeadPtr],y	sta <widMax; now set fast head ptr to point to the width table!	lda <fastHeadPtr	clc	adc #o_FFSizeofVars	sta <fastHeadPtr	bcc @5	inc <fastHeadPtr+2@5; use the following once we need it!	rtl;; Fast multiply routine, just in case I need it for something!;	Export DoMultiplyDoMultiply	ldx #0	; init our carry over area	lda #0dm0010	lsr Mult1	; shift for first test	beq dmLastOne	; handle the last multiply	bcc dm0020	clc	adc Mult2	bcc dm0020	; if carry clear we didn't role the bank yet..	inx	; if carry set, role the bank!dm0020	asl Mult2	bra dm0010dmLastOne	bcc done	clc	adc Mult2	bcc done	; carry clear no bank role	inxdone	;	sta Mult1	; turns out wo don't need to save em..;	stx Mult2	rts	lMaskTbl	dc.W $FFFF	dc.W $FF3F	dc.W $FF0F	dc.W $FF03rMaskTbl	dc.W $FFFF	; this table is gonna be a bit bigger...	dc.W $00C0	; 1 pixel	dc.W $00F0	dc.W $00FC	dc.W $00FF	dc.W $C0FF	dc.W $F0FF	dc.W $FCFF	ENDP	EJECT********************************************************************************FastPutChar	PROC Export** Description:	This routine draws a character to the current grafport*	as fast as its little legs can make it do it!* Setup* SrcRef - Set to the character to draw's offset into the proper strike* destRef- Set to the grafports destination location* maskleft & maskRight - set for masking the characters properly* theWidth - set to the current characters width* shiftInfo - set to number of pixels to shift *2*********************************************************************************; first test to see if we need any right mask...	lda <ascent	; get the proper number of 	clc	; lines to draw+1	adc <descent	sta <CharToDraw	; and use it as our counter; NOTE: we can blow away char to draw now!	phb	; save the current data bank	pei <destRef+1	; get the source ref bank	plb	plb	; and get the destination bank number..	lda <fastMode	; get the mode	cmp #$0004	bne @modeCopy	brl FastModeForeCopy@ModeCopy	lda <shiftInfo	bne needBothMasks	lda <theWidth	adc #7	lsr a	; compute the number of words to copy	lsr a	lsr a	cmp #4	; if its greater than 3 words, use long way	bge theLongWay	; gotta use the long way here!	asl a	; use as table offset...	tax	; use it # bytes as a table lookup	jsr (rMaskOnly,x)	; and jump to the proper routinerMaskOnly0	plb	rts; table of routines that copy the data using only the right mask...rMaskOnly	dc.W rMaskOnly0	; can never happen... but	dc.W rMaskOnly2	; a whole word...	dc.W rMaskOnly4	; 2 words...	dc.W rMaskOnly6needBothMasks	lda <shiftInfo	; get the shift info back...	clc	adc <theWidth	; and create the number of pixels to xfer..	adc #7	lsr a	; compute the number of words to copy	lsr a	lsr a	cmp #4	; if its greater than 3, use long way	bge theLongWay	; may as well use bofth masks!	asl a	; use as table offset...	tax	; use it # bytes as a table lookup	pei <fastMaskLeft	; save this	jsr (bothMaskTbl,x)	; and jump to the proper routinebMask0	pla	sta <fastMaskLeft	plb	rtsbothMaskTbl	dc.W bMask0	; can never happen... but	dc.W bMask2	dc.W bMask4	dc.W bMask6;; The next routine is the routine that will copy the character to the screen ; the long way... its kinda slow, but hey, why are you using such wide characters?theLongWay	asl a	; multiply by 2...	sbc #1	; carry is set, subtract 2 from this...	sta <theWidth	; save width in bytes of the character...	lda [<srcRef]	; get the first word to slam...	eor (<destRef)	and <fastMaskLeft	; do the first word...	eor (<destRef)	sta (<destRef)	ldy #2@Loop	lda [<srcRef],y	; get the first word to slam...	sta (<destRef),y	iny	iny	cpy <theWidth	; are we there yet???	blt @loop	; if not, do another 2...	lda [<srcRef],y	; get the first word to slam...	eor (<destRef),y	and <fastMaskright	; do the last word...	eor (<destRef),y	sta (<destRef),y	dec <charToDraw	; decrement our counter...	beq @Done;; bump our counters...	lda <width	clc	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	ldy #0	bra @Loop@Done	plb	rts	; and exit;; This is the start of all our special case routines...; strap in, they are pretty long and fast...rMaskOnly2	ldx <CharToDraw@loop	lda [<srcRef]	eor (<destRef)	and <fastMaskRight	eor (<destRef)	sta (<destRef)	dex	beq @Done	lda <width	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	bcc @2	inc srcRef+2	clc@2	bra @loop@Done	rts;; This routine slams 4 bytes applying the left mask to the final word; rMaskOnly4	ldx <CharToDraw	ldy #2@Loop	lda [<srcRef]	; get the first word to slam...	sta (<destRef)	; and slam it out...	lda [<srcRef],y	eor (<destRef),y	and <fastMaskRight	eor (<destRef),y	sta (<destRef),y	dex	beq @Done	lda <width	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	bcc @2	inc srcRef+2	clc@2	bra @Loop@Done	rts	; and exit;; This routine slams 6 bytes applying the left mask to the final word; rMaskOnly6	ldx <CharToDraw@Loop	ldy #2	lda [<srcRef]	; get the first word to slam...	sta (<destRef)	; and slam it out...	lda [<srcRef],y	sta (<destRef),y	ldy #4	lda [<srcRef],y	eor (<destRef),y	and <fastMaskRight	eor (<destRef),y	sta (<destRef),y	dex	beq @Done	lda <width	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	bcc @2	inc srcRef+2	clc@2	bra @Loop@Done	rts	; and exitbMask2	lda <fastMaskRight	and <fastMaskLeft	sta <FastMaskRight	brl rMaskOnly2	; and reuse some code...;; This routine slams 4 bytes applying the left mask and right mask to the final word; bMask4	ldx <CharToDraw	ldy #2@Loop	lda [<srcRef]	; get the first word to slam...	eor (<destRef)	and <fastMaskLeft	eor (<destRef)	sta (<destRef)	lda [<srcRef],y	eor (<destRef),y	and <fastMaskRight	eor (<destRef),y	sta (<destRef),y	dex	beq @Done	lda <width	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	bcc @2	inc srcRef+2	clc@2	bra @Loop@Done	rts	; and exit;; This routine slams 6 bytes applying the both masks to the final word; bMask6	ldx <CharToDraw@Loop	ldy #2	lda [<srcRef]	; get the first word to slam...	eor (<destRef)	and <fastMaskLeft	eor (<destRef)	sta (<destRef)	lda [<srcRef],y	sta (<destRef),y	ldy #4	lda [<srcRef],y	eor (<destRef),y	and <fastMaskRight	eor (<destRef),y	sta (<destRef),y	dex	beq @Done	lda <width	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	bcc @2	inc srcRef+2	clc@2	bra @Loop@Done	rts	; and exit;; This routine bumps the bank of the destination we are using bumpBank	phb	; push the current bank	pla	inc a	pha	plb	clc	rtsFastModeForeCopy; The next routine is the routine that will do a pseudo fast modeForecopy of; all the words in our character; its kinda slow, but hey, why are you using modeForeCopy?	lda <shiftInfo	; get the shift info back...	bne @maskOK	dec a	sta <fastMaskLeft	inc a@MaskOK	clc	adc <theWidth	; and create the number of pixels to xfer..	adc #7	lsr a	; compute the number of words to copy	lsr a	lsr a	asl a	; multiply by 2...	sbc #1	; carry is set, subtract 2 from this...	sta <theWidth	; save width in bytes of the character...	lda <fastMaskLeft	; convert the left mask	eor #$FFFF	; by inverting it...	sta <fastMaskLeft	lda <fastMaskRight	; convert the left mask	eor #$FFFF	; by inverting it...	sta <fastMaskRight; Start the loop here!@outerLoop	ldy #2	lda <theWidth	cmp #2	; are we doing 2 words or less	bge @cont; modeforecopy 1 word...	lda [<srcRef]	; get the first word to slam...	ora <fastMaskLeft	ora <fastMaskRight	and (<destRef)	sta (<destRef)	bra @drawCont@cont	bne @cont2		lda [<srcRef]	; get the first word to slam...	ora <fastMaskLeft	and (<destRef)	sta (<destRef)	bra @DoLastWord@Cont2	lda [<srcRef]	; get the first word to slam...	ora <fastMaskLeft	and (<destRef)	sta (<destRef)@Loop	lda [<srcRef],y	; get the first word to slam...	and (<destRef),y	; do the modeforecopy and	sta (<destRef),y	iny	iny	cpy <theWidth	; are we there yet???	blt @loop	; if not, do another 2...@DoLastWord	lda [<srcRef],y	; get the first word to slam...	ora <fastMaskright	; do the last word...	and (<destRef),y	sta (<destRef),y@DrawCont	dec <charToDraw	; decrement our counter...	beq @Done;; bump our counters...	lda <width	clc	adc <destRef	sta <destRef	bcc @1	jsr BumpBank	; bump the data bank and clear the carry@1	lda <RowBytes	adc <srcRef	sta <srcRef	bcc @2	inc <srcRef+2	clc@2	brl @outerLoop@Done	plb	rts	; and exit	EndP******************************************		**  end of DChar		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    5:00 PM, 4/15/86	**		******************************************;********************************************************************************			                  **              subroutine DText (alias DCstring)	                  **			                  **		started 4/2/86 or before              **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this is the framing routine used by DrawString, DrawText, and   **  DrawCstring to draw a sequence of characters into the current grafport's   **  pixelmap.  It does everything those routines want - see external documen-  **  tion.			                  **			                  **  ASSUMPTIONS:  Very few.  QD II must be active.  DrawVerb	must be set.      **  TextPtr and (for	strings and text blocks) TextLength must also be set.     **			                  **  RETURNS:  pnLoc.H in the current grafport is increased by the entire       **  string width, regardless of whether all, some, or none of the characters   **  actually got drawn into the destination.	                  **			                  **  ALTERS:  most if	not all of the QD II globals may be changed by this rou-  **  tine.			                  **			                  **  NOTES:  a lot of	DText's code is dedicated to determining which characters **  in a string (or whatever) can actually impinge on the destination pixel-   **  map; the ones that can't it doesn't even draw into the text buffer.  This  **  lets us avoid having a text buffer as big as all outdoors.                 **			                  **  The distinction between strings (and	text blocks) and Cstrings is only     **  of interest to one subroutine - GetNextChar, which distinguishes them on   **  the basis of DrawVerb.  This allows us to use identical code for the diff- **  erent text data structures, once DrawVerb is set.  (the difference between **  strings and text	blocks is taken care of even earlier, in DrawString and   **  DrawText; they even have the same DrawVerb value)	                  **			                  **  The DBR is preserved.		                  **			                  **  DText returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 4/2/86		**    Dan's bug (letters to the left of  **    port screw things up) fixed by	**    changing an errant ADC #lowByte	**    to AND #lowByte - 4/15/86, BHM	**		**    changed to handle spExtra; doc.	**    not up to date	- BHM, 4/22/86	**		**    spExtra taken out for a while;	**    style mods put	in - 5/2/86, BHM	**		*  ** 2/12/89	Mensch** Added some more of the fast text stuff. Added a new loop in this routine for* drawing fast chars, this should speed up drawing the chars...*                 *****************************************;	EXPORT iDTextiDText	PROC	EXPORT iDCstringiDCstring		;       *              USING E0Vectors*              USING CoreData;	jsl GetNextChar	bcc NotNullString	rtl	;null string.  Not much to do.;NotNullString		; ;	jsl PortLoc2ZP	jsl SetUpPortRegions;	lda #-1	; get the fast font info if available	jsl SetUpFontInfo;	ldy #(O_pnLoc+O_H)	lda [portRef],y	;get current pnLoc.H	sta currPen;	jsl CalcDrawStatus	;check for invis. pen or null minRect	bcc GoodDrawStatus;bad draw status:	jsl BumpPen	;bump currPen by string width	brl BadDrawStatus;GoodDrawStatus		; ;; test to see if we are using the pre-cached font stuff...	php	bit <fontFlags	bvs @stillfast	plp	bra doOldLine@StillFast	plp	ldy #o_font+2;	lda [<portRef],y;	bpl doOldLine	bvc BadFastLine	; if the regions are non-rectangular no fast stuff	brl tryFastLine	; if set try drawing a fast line!;BadFastLine	lda #0	; get the original font info...	jsl SetUpFontInfo	; and call the font info setup stuffdoOldLine;****  TURNED IN-LINE CODE INTO SUBROUTINE;	jsl CalcSlop	;this subroutine, in particular;****  END OF CHANGE	- 2/9/87  BHM  x6245;**** ADDED 3/10/87 DUE TO CHANGES IN CALCSLOP;	ldx #512	lda fontSlop,x;****  END OF CHANGE	- BHM  x6245;	sta temp;	lda minRect+O_H2	clc	adc temp;any character from	this font starting from a pnLoc.H > that sum;won't show up in the destination pixelmap	cmp currPen	bpl NtAllPstRight	;"not all past right" limit;not so -  all the characters are beyond the right boundary	of the minRect:	jsl BumpPen	;bump currPen by string width	brl AllPastRight;NtAllPstRight		; 	sta rightLimit;	lda minRect+O_H1	sec	sbc temp	sta leftLimit;any character with	pnLoc.H < leftLimit	won't show up in destination;NextChar1		; 	lda currPen	cmp leftLimit	bpl InMinBounds	;character MAY show	up in destination;no way:	jsl ValidChar	and #lowByte	;get width of character	clc	adc currPen	;boost current pen	sta currPen;	jsl GetNextChar	bcc NextChar1	;and go to next character;there wasn't any - all were too far left:	brl AllTooFarLeft;InMinBounds		; ;characters which have a chance of impinging;on the current grafport's minRect come here;	jsl SetUpBufInfo;	lda rightLimit	;in local coordinates	sec	sbc hBufToLoc	sta bufRightLimit	;same, but in buffer coordinates;NextChar2		; ;transfer character	image from font strike to text buffer:;	jsl PutChar;	jsl GetNextChar	bcc MoreChars;no more:	lda bufPen	;new pen position, buffer coordinates	clc	adc hBufToLoc	;now local coordinates	sta currPen	bra DrewLastChar;MoreChars		; ;but will they fit?	lda bufRightLimit	cmp bufPen	bpl NextChar2	;yes;no:	lda bufPen	clc	adc hBufToLoc	sta currPen	jsl BumpPen	;boost currPen by any remaining chars;;and fall into . . .;DrewLastChar		; ;at least some characters were drawn into text buffer -;perform style mods:	jsl StyleText;and see if any of the image  actually makes it into destination	jsl TextAndMinRect	bcs NullInt	;no - null intersection;yes - get parameters for buffer-to-pixelmap transfer:	jsl CalcTextBounds	jsl BlowItUp	;and DO IT!;NullInt		; 	jsl CleanUpBuffer;BadDrawStatus		; AllPastRight		; AllTooFarLeft		; ;	lda currPen	ldy #(O_pnLoc+O_H)	sta [portRef],y	;put updated pen into grafport;;	jsl FreePortRegions;	rtl	;there's no place like home;; Added 2/12/89	MenschtryFastLine; This routine should be called when the font handle indicates that a fastfont is; being used, if fastfonts are being used, this loop will attempt to draw them; in the proper place on the screen. NOTE: this routine calls some routines that are; in iDChar as well... Note that on entry to this routine, charTodraw is preset ; for us already!;	lda #-1	sta <fastLineStat	ldy #o_PnLoc+o_V	; offset to pen loc.v	lda [<portRef],y	clc	; set to add an extra 1	adc <descent	; add the fonts descent to this value	cmp <MinRect+o_V2	; see if we are within bounds...	beq @1	bpl notWhole	; this is the bottom@1	sta <minRect+o_V2; NOTE: this next subtract RELY's on the carry being clear from above compare!	sec	sbc <descent	; now create the top of our character rectangle	sbc <ascent	; by subtracting the character ascent and decsent	sta <charRect+o_V1	cmp <MinRect+o_V1	; see if we are too high	bmi notWhole	sta <MinRect+o_V1	lda <CurrPen	; offset to penloc.H	sta <charRect+o_H1	; make this the right edge	cmp <MinRect+o_H1	bmi NotWhole	sta <MinRect+o_H1; now get the right edge...	jsl validChar	; get the width of the character	cmp #13	; see if its too big...	blt @2	lda #12	; max char width = 12...@2	clc	sta <theWidth	; save the width of this character	adc <charRect+o_H1	cmp <minRect+o_H2	bpl notWhole	bra goFast	; if we get this far, we can do the fast drawingnotWhole	brl badFastLine	; if not whole, just do it the old way...notWhole2		jsl UnShieldCursor	; the cursor was shielded, unshield it... 	brl badFastLine	; and now continue to draw the old way...;; If we get this far, then we can go the fast way!goFast; we must now convert our rectangle to 'global' locinfo coordinants; we do this by first creating an 'offset' to add to our rectangle... NOTE: this now only; operates on the top left	lda <charRect+o_V1	sec	sbc <boundsRect+o_V1	bmi notWhole	; if this is negative, somethings wrong..	sta charRect+o_V1		lda <charRect+o_H1	sec	sbc <boundsRect+o_H1	bmi notWhole	; if this is negative, somethings wrong..	sta charRect+o_H1	jsl ShieldCursor	; shield the cursor for the whole line	lda <width	cmp #$00A0	; special case for screen port rects	bne @doMult1	lda charRect+o_V1	; get the character rectangle top	cmp #400	; see if we rolled over the top of the mult below	bge @DoMult2	asl a	; multiply it by 32 first..	asl a	asl a	asl a	asl a	sta Mult1	asl a	asl a	clc	adc Mult1	ldx #0	bra @DoMult3@DoMult2	lda <width@DoMult1	sta Mult2	; save it for the multiply	lda charRect	; get the v1 coordinant	sta Mult1	jsr DoMultiply	; multiply these two numbers@DoMult3; once we have it this far, we can create the address of the starting scan line to ; draw upon...	adc <imageRef	; add to the base image reference	sta Mult1	; save this for a second...	txa	adc <imageRef+2	; and create the high word	sta Mult2	bra LoopCont	; branch around each char stuff;; InnerLoop now bypasses many of the above tests that no longer need to be performed;InnerLoop	lda <CurrPen	; offset to penloc.H	sta <charRect+o_H1	; make this the left edge; now get the right edge...	jsl validChar	; get the width of the character	cmp #13	; see if its too big...	blt @2	lda #12	; max char width = 12...@2	sta <theWidth	; save the width of this character	adc <charRect+o_H1	cmp <minRect+o_H2	bpl notWhole2	; call thisway cause cursor shielded...; and convert the new position to global coordinants.	lda <charRect+o_H1	sec	sbc <boundsRect+o_H1	bmi notWhole2	; if this is negative, somethings wrong..	sta charRect+o_H1	; call thisway cause cursor shielded...;; Now that the char is converted to 'local coordinants lets just call the drawing; routine!LoopCont; We must enter DrawOneFromALine with DestRef calculated...	lda Mult2	sta DestRef+2	lda <CharRect+o_H1	; now compute the offset into destref	lsr a	; divide this by 4(pixels per byte)	lsr a	clc	; and add it in creating our final offset	adc Mult1	sta destRef	bcc @1	inc DestRef+2@1	jsr DrawOneFromaLineLoopCont1	jsl GetNextChar	; get the next character...	bcc gotNextOne	jsl UnShieldCursor	brl AllTooFarLeft	; we got the last char, we can end now!gotNextOne	brl InnerLoop	ENDP;;****  NEW SUBROUTINE - ADDED 2/9/87****  (USED TO BE PART OF DTEXT);	EXPORT iCalcSlopiCalcSlop	PROC;	ldx #256	lda fontWidth,x	bne ForcedWidth;"default" width calculation:	lda fRectMax	cmp widMax	bpl GotMax	lda widMaxGotMax		; 	clc	adc extra;	clc	adc chExtra+2	;add in high word of fixed point	ldx chExtra	beq chDoNotRound	;low byte 0 - don't round	inc a	;roundchDoNotRound		; 	clc	adc spExtra+2	;same for spExtra	ldx spExtra	beq spDoNotRound	inc aspDoNotRound		; ForcedWidth		; ;;	inc a;****  ADDED 3/10/87	TO IMPROVE USABILITY OF THIS SUBROUTINE;	ldx #512	sta fontSlop,x	;everyone will know	to find it here;****  END OF CHANGE	- BHM  x6245;	rtl;	ENDP;****  END OF NEW SUBROUTINE - BHM  x6245;******************************************		**  end of DText (alis DCstring)	**		******************************************;;                copy text/TxBoundsCalls****************************************************************** CharBounds*              theChar     word (input)*              theRectPtr  long (input)	               ******************************************************************	EXPORT CharBoundsCharBounds	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3theRectPtr	equ RTL2+3theChar	equ theRectPtr+4;rectPtr	equ fontTemp	jsr QDStart	lda TheChar,s	sta charToDraw	lda theRectPtr,s	sta rectPtr	lda theRectPtr+2,s	sta rectPtr+2	lda #DrawCharVerb	jsl CallTxBounds	jmp BusyEC6	ENDP****************************************************************** StringBounds*              StringPtr     long (input)*              RectPtr       long (input)           *****************************************************************	EXPORT StringBoundsStringBounds	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3theRectPtr	equ RTL2+3StrPtr	equ theRectPtr+4;rectPtr	equ fontTemp	jsr QDStart	lda StrPtr,s	sta TextPtr	lda StrPtr+2,s	sta TextPtr+2	lda [TextPtr]	and #lowByte	sta TextLength	IncLong TextPtr	lda theRectPtr,s	sta rectPtr	lda theRectPtr+2,s	sta rectPtr+2	lda #DrawTextVerb	jsl CallTxBounds	jmp BusyEC8	ENDP****************************************************************** TextBounds*              PtrToText    long (input)*              TextLength   word (input)*              RectPtr      long (input)*** ChangeHistory** 21 Aug 86    SEG for BM    The equates were off by 1.*****************************************************************	EXPORT TextBoundsTextBounds	PROC*              USING PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3theRectPtr	equ RTL2+3TheTextLength	equ theRectPtr+4TheTextPtr	equ TheTextLength+2;rectPtr	equ fontTemp	jsr QDStart	lda TheTextPtr,s	sta TextPtr	lda TheTextPtr+2,s	sta TextPtr+2	lda TheTextLength,s	sta TextLength	lda theRectPtr,s	sta rectPtr	lda theRectPtr+2,s	sta rectPtr+2	lda #DrawTextVerb	jsl CallTxBounds	jmp BusyEC10	ENDP****************************************************************** CStringBounds**              CStrPtr   long (input)*              RectPtr   long (input)* TopOfStack   ======================** Modification History** 19 May 86    This	routine was reading	the parameters off the*              stack backwards.  The equates are changed to*              do this right.*****************************************************************	EXPORT CStringBoundsCStringBounds	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3theRectPtr	equ RTL2+3CStrPtr	equ theRectPtr+4;rectPtr	equ fontTemp	jsr QDStart	lda CStrPtr,s	sta TextPtr	lda CStrPtr+2,s	sta TextPtr+2	lda theRectPtr,s	sta rectPtr	lda theRectPtr+2,s	sta rectPtr+2	lda #DrawCStrVerb	jsl CallTxBounds	jmp BusyEC8	ENDP****************************************************************** CallTxBounds** This routine called by the entry points standard* text inputs are on zero page.** Zero page is already switched in by the time it gets here.*****************************************************************	EXPORT CallTxBoundsCallTxBounds	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	sta DrawVerb	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdTxBndsUseLocal	phb	; put extra byte on	stack	ldy #o_stdTxBnds	; get adr of new text width routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** StdTxBnds** Common text measuring routine that is	central point for* all text framing routines.** When control gets	here, all inputs are on zero page.** There are lots of	possiblities as to what they are.  And the* Draw verb is what	tells us what to do.**       For CharWidth*               char is on zp at charToDraw**       For TextWidth*               pointer is on zp*               length is on zp**       For CStringWidth*               pointer is on zp*****************************************************************	EXPORT iStdTxBndsiStdTxBnds	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	lda DrawVerb	; put verb in a	asl a	tax	jmp (DoBoundsTable,x)DoBoundsTable		; 	DC.W iBChar	DC.W iBText	DC.W iBCString	ENDP****************************************************************** BChar*****************************************************************	EXPORT iBChariBChar	PROC*              USING E0Vectors*              USING CoreData;rectPtr	equ fontTemptheWidthOfChar	equ temptheLocTEnt	equ temp+2theImageWidth	equ temp2;	lda #0	jsl SetUpFontInfo;	ldy #(O_pnLoc+O_H)	lda [portRef],y	;current pen position (hor.)	sta startBufPen;	jsl ValidChar	tax	;temp. storage	and #lowByte	;character width	clc	adc startBufPen	;bump pen	sta bufPen;	lda [locTPtr],y	MacSwitch	sta theLocTEnt	iny	iny	lda [locTPtr],y	MacSwitch	sec	sbc theLocTEnt	;get image width	bne Not0Width	brl ZeroWidth	;null image;Not0Width		; 	sta theImageWidth	txa	;get back offset/width value	xba	and #lowByte	;character offset	clc	adc kernMax	clc	adc startBufPen	sta leftExtent;	clc	adc theImageWidth	sta rightExtent;modify extents to reflect any style mods:	jsl StyleExtents;	lda leftExtent	cmp startBufPen	bpl SBPOK	;startBufPen is leftmost;or it's not:	sta startBufPenSBPOK		; ;	lda rightExtent	cmp bufPen	bmi BPOK	;bufPen is rightmost	sta bufPen	;or at least it is nowBPOK		; ;;leftmost and rightmost extents now in startBufPen and bufPen -;put them in the target rectangle:;ZeroWidth		; 	lda startBufPen	ldy #O_H1	sta [rectPtr],y;	lda bufPen	ldy #O_H2	sta [rectPtr],y;now take care of verticals:	ldy #(O_pnLoc+O_V)	lda [portRef],y	;current pen position (vert.)	tax	;temp. storage	sec	sbc ascent	ldy #O_V1	sta [rectPtr],y;	txa	clc	adc descent	ldy #O_V2	sta [rectPtr],y;;	rtl	ENDP******************************************		**  end of BChar		**		************************************************************************************************************ BText (alias BCstring)******************************************************************	EXPORT iBTextiBText	PROC	EXPORT iBCStringiBCString		;       *              USING E0Vectors*              USING CoreData;rectPtr	equ fontTemptheWidthOfChar	equ temptheLocTEnt	equ temp+2theImageWidth	equ temp2;	ldy #(O_pnLoc+O_H1)	lda [portRef],y	sta startBufPen	sta bufPen;	lda #maxInt	sta leftExtent	lda #(-maxInt)	sta rightExtent;	jsl GetNextChar	bcc NotNullString	brl NullString;NotNullString		; ;	lda #0	jsl SetUpFontInfo;NextChar		; 	jsl ValidChar	tax	;temporary storage	and #lowByte	sta theWidthOfChar;	lda bufPen	sta imagePen	clc	adc theWidthOfChar	sta bufPen	;bump position by char width;	lda [locTPtr],y	MacSwitch	sta theLocTEnt	iny	iny	lda [locTPtr],y	MacSwitch	sec	sbc theLocTEnt	bne Not0Width	brl ZeroWidth	;don't touch extentsNot0Width		; ;	sta theImageWidth;	txa	;get back offset/width value	xba	and #lowByte	;offset	clc	adc kernMax	clc	adc imagePen	tax	;temp. storage	cmp leftExtent	bpl leftOK	;leftExtent is leftmost pixel	sta leftExtent	;or, it is nowleftOK		; ;;new "imagePen" value still in acc.	clc	adc theImageWidth	cmp rightExtent	bmi RightOK	;rightExtent is rightmost pixel	sta rightExtent	;sooner or laterRightOK		; ZeroWidth		; ;	jsl GetNextChar	bcc NextChar	;if there is one;;there wasn't:;adjust extents to reflect any style mods:	jsl StyleExtents;;and fall into . . .;NullString		; 	lda leftExtent	cmp startBufPen	bmi leftStillOK	lda startBufPen	;winner and new championleftStillOK		; 	ldy #O_H1	sta [rectPtr],y;	lda rightExtent	cmp bufPen	bpl rightStillOK	lda bufPenrightStillOK		; 	ldy #O_H2	sta [rectPtr],y;;now take care of verticals:	ldy #(O_pnLoc+O_V)	lda [portRef],y	;current pen position (vert.)	tax	;temp. storage	sec	sbc ascent;	ldy #O_V1	sta [rectPtr],y;	txa	clc	adc descent	ldy #O_V2	sta [rectPtr],y;;	rtl	ENDP******************************************		**  end of BText (alias BCstring)	**		******************************************;                copy text/OtherTextCalls;;This version of GetFontInfo has been broken up to make it easier;to change and/or patch out later.  It should replace the old;GetFontInfo in the	new ROM.;****************************************	                  **  Feb. 9, 1987  1:00 pm              **	                  **  Bennet Marks  x6245                **	                  ****************************************;****************************************************************** GetFontInfo** Returns some information about the font.*****************************************************************GetFontInfo	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3FIPtr	equ RTL2+3	jsr QDStart;	lda FIPtr,s	sta temp2	lda FiPtr+2,s	sta temp2+2;	jsl GetFntInf;	jmp BusyEC4;	ENDP;*****************************************************************iGetFntInf	PROC EXPORT** A vectored routine to do the work for GetFontInfo.* Calling routine sets up temp2 to point to the destintation* record.*** Inputs:*	temp2*	Current Port** Outputs:*	Font INfo Record** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;	lda #0	jsl SetUpFontInfo;(that gives us far	more than we need, but it's ok);	lda ascent	sta [temp2];	lda descent	ldy #o_FoInDescent	sta [temp2],y;	lda widMax	clc	adc extra	ldy #o_FoInWidmax	sta [temp2],y;	lda leading	ldy #o_FoInLeading	sta [temp2],y;	rtl	ENDP;;*****************************************************************GetFGSize	PROC EXPORT** Returns the current size of the Font Globals record.  This* call is provided so that we may add information in the* header area of the font.*** Inputs:*	none** Outputs:*	word : Size of globals in bytes** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3theFGSize	equ RTL2+3;	jsr QDStart;	jsl GetFGS	sta theFGSize,s;	jmp BusyEC0;	ENDP*****************************************************************iGetFGS	PROC EXPORT** Vectored routine that loads the a-reg with current size of* font globals.*** Inputs:*	none** Outputs:*	a-reg** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #FGSize	rtl			ENDP*****************************************************************TextDeref	PROC EXPORT** Short routine to deref the handle in a & x and return the pointer* in a & x.** Temp is destroyed.*** Inputs:*	handle in a & x reg** Outputs:*	pointer in a & x reg*	temp is destroyed.** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	sta TEMP	stx TEMP+2	ldy #2	lda [TEMP],y	tax	lda [TEMP]	rts	ENDP;Tuesday, Nov. 11, 1986  2:15 pm;BHM  x6245;;  GetRomFont;;This QDII call returns information on the ROM font.  It accepts a;pointer, and returns an RFRec in the buffer pointed to.  The;RFRec has the form;;  famNum;  style;  size;  handle  {handle to ROM font};  namePtr {pointer	to ROM font name};  fbrExtent;;for a total of 16 bytes.  The main point of this call is to shield the;application from the fact that the V.1.0 ROM font doesn't have legal;values for some of	those fields.;;This code is only good for the V.1.0 ROM.  Future versions	of this call;will be built into	ROM, and reflect any changes in the ROM	font.;	EXPORT GetRomFontGetRomFont	PROC;OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3RFRecPtr	equ RTL2+3;	jsr QDStart;	lda RFRecPtr,s	sta fontTemp	lda RFRecPtr+2,s	sta fontTemp+2;	jsl GetRFRec;	ldy #4	jmp BusyEC;	ENDP;	EXPORT GetRFRecGetRFRec	PROC;;	lda #rfFamNum	sta [fontTemp];	lda #rfStyle	ldy #o_RFStyle	sta [fontTemp],y;	lda #rfSize	ldy #o_RFSize	sta [fontTemp],y;	lda #^SystemFont	ldy #(o_RFHandle+2)	sta [fontTemp],y	lda #SystemFont	ldy #o_RFHandle	sta [fontTemp],y;	lda #^rfName	ldy #(o_RFNamePtr+2)	sta [fontTemp],y	lda #rfName	ldy #o_RFNamePtr	sta [fontTemp],y;	lda #rfFBRExtent	ldy #o_RFFBRXtnt	sta [fontTemp],y;	rtl;rfName	DC.B 7rfNameStr	DC.B 'Shaston'	ENDP	EJECT********************************************************************************SetUpFontHeadPtr	PROC Export** Description:	This routine derefs the current grafports font handle and*	stuffs the derefed version of it in FontHeadPtr. This should*	be called by any routine that wants to look at the font *	record directly. ** NOTE:	This routine modifies temp*** Inputs:	NotMuch** Outputs:	FontHeadPtr** External Refs:** Entry Points:********************************************************************************	ldy #(O_font+2)	lda [portRef],y	;font handle high word	bpl standardFont	; if high bit clear we are using a standard fontloadStdData	sta temp+2	; get the handle to the fastfont stuff	ldy #o_font	lda [portRef],y	sta temp	lda [temp]	; and deref it...	sta fontHeadPtr	ldy #2	lda [temp],y	sta fontHeadPtr+2;	ldy #o_oldFontHandle ; offset to the old font..	lda [fontHeadPtr],y	; get the old font handle	sta temp	ldy #o_oldFontHandle+2	lda [fontHeadPtr],y	sta temp+2	; set temp to be the old font handle	bra SF0010	; and branch into standard font stuff	standardFont	sta temp+2	dey	dey	lda [portRef],y	sta temp;SF0010	lda [temp]	sta fontHeadPtr	ldy #2	lda [temp],y	sta fontHeadPtr+2	rtl	EndP;;  The following version of GetFontGlobals should go into;  the 1.1 ROM, along with the new ROM font*****************************************************************************;  Feb. 6, 1987;  BHM  x6245;;  GetFontLore;;This call returns information about a font just like GetFontGlobals;does.  However, it	takes a maximum buffer size parameter, and will;not overflow a buffer of that size.  GetFontLore also returns (on the;stack) the number of bytes that it actually returned.  This can be;less than the given max buffer size for a variety of reasons (for example,;there aren't that many bytes of font lore currently defined, or the max;cutoff comes in the middle of a field).  Any space in the buffer after;that number of bytes will be untouched	by this call.;;GetFontGlobals uses this same code, with some massaging up	front.;** Change History* 7/23/87       GCP	    corrected typo.	temp+2 had been incorrectly entered*	     as temp2+2.*	    Replaced jsr BusyEC with BusyEC6.** 13 Oct 88    SMD      the Apple IIGS font header now has 14 bytes due to the*	    addition of "highOwTLoc", the high word of the offset*	    to the offset width table.  GetFontLore has been modified*	    to return this new field if the version is >= 1.02** 30 Dec 88	Steven Glass** Made jmp BusyEC6 into jml BusyEC6 so this can be used in patch.******************************************************************************GetFontLore	PROC EXPORT;OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3maxSize	equ RTL2+3FLPtr	equ maxSize+2trueSize	equ FLPtr+4;	jsr QDStart;	lda maxSize,s	sta temp2;	lda FLPtr,s	sta fontTemp	lda FLPtr+2,s	sta fontTemp+2;	jsl GetFL;	lda temp2	sta trueSize,s;	jml BusyEC6;	ENDP;;GetFL	PROC EXPORT;; Changed 3/2/89 Mensch; Modified this routine so that it is compatible with fastfont stuff	jsl SetUpFontHeadPtr;	lda [fontHeadPtr]	asl a	clc	adc fontHeadPtr	sta fontRecPtr	lda fontHeadPtr+2	bcc @NoCarry	inc a	@NoCarry	sta fontRecPtr+2;	ldx temp2	stz temp2;	dex	dex	bpl Field1	brl NoMoreLore;Field1		; 	ldy #o_FamNum	lda [fontHeadPtr],y	ldy #o_FLFamNum	sta [fontTemp],y	inc temp2	inc temp2;	dex	dex	bpl Field2	brl NoMoreLore;Field2		; 	ldy #o_Style	lda [fontHeadPtr],y	ldy #o_FLStyle	sta [fontTemp],y	inc temp2	inc temp2;	dex	dex	bpl Field3	bra NoMoreLore;Field3		; 	ldy #o_Size	lda [fontHeadPtr],y	ldy #o_FLSize	sta [fontTemp],y	inc temp2	inc temp2;	dex	dex	bpl Field4	bra NoMoreLore;Field4		; 	ldy #o_Version	lda [fontHeadPtr],y	ldy #o_FLVersion	sta [fontTemp],y	inc temp2	inc temp2;	dex	dex	bpl Field5	bra NoMoreLore;Field5		; 	ldy #o_MaxWd	lda [fontRecPtr],y	ldy #o_FLMaxWd	sta [fontTemp],y	inc temp2	inc temp2;	dex	dex	bpl Field6	bra NoMoreLore;Field6		; 	ldy #o_fbrExtent	lda [fontHeadPtr],y	ldy #o_FLFBRXtent	sta [fontTemp],y	inc temp2	inc temp2********* SMD - provide for highOwTLoc field********	dex	dex	bpl Field7	bra NoMoreLore	Field7	ldy #o_Version	lda [fontHeadPtr],y	cmp #V0102	;compare to Version 1.02	bmi NoMoreLore	ldy #o_highOwTLoc	;SMD - Version 1.02 or greater	lda [fontHeadPtr],y	sta [fontTemp],y	inc temp2	inc temp2;NoMoreLore		; 	rtl	ENDP	;                copy text/itb;Monday, Nov. 17, 1986  2:30 pm;;QD II call InflateTextBuffer;;This call takes 2 inputs, a font width	and a font height.	If;a font with this width and height would require a text buffer;either wider or taller than the current text buffer (or both),;the call resizes the text buffer.  The	resulting text buffer;will be at least as wide and tall as the old one, and will;also be wide and tall enough for the (hypothetical) font.	The;call also clears the new text buffer.;;If the current text buffer is already large enough (in both;directions) for the given width and height, the call leaves;it alone.;;Forced vs. unForced (the great albatross around the neck of;the text buffer subroutines):;;InflateTextBuffer does not allow the new font width to be forced;;it will always pad	that value.  If the	old font width was forced,;the new one will also be marked as forced.  For its forced	font;width value, it will use the old forced font width OR the new value;AFTER IT'S BEEN PADDED - whichever is larger.;;"font width" means	fbrExtent, of course.;	EXPORT InflateTextBufferInflateTextBuffer	PROC;;This is the shell:;OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3newHeight	equ RTL2+3newWidth	equ newHeight+2;	jsr QDStart	lda newWidth,s	sta newFontWidth	lda newHeight,s	sta newTBHeight*** added 3-Dec-91 DAL -- preserve old DP values that we may need to restore	ldx #256	lda <fontWidth,x	pha	pei <textBufHeight	pei <textBufRowWords*** end 3-Dec-91	jsl InflateTB;;;;	ldy #4;;;	jmp BusyEC*** added 3-Dec-91 DAL -- honor error code from InflateTB, and restore***  DP values if we had an error (even though QD doesn't mess up the***  values if it can't resize the buffer, we do mess them up if QD Aux***  can't resize -its- buffers).	tay	;error code to Y	pla	bcc @noStore1	sta <textBufRowWords@noStore1	pla	bcc @noStore2	sta <textBufHeight@noStore2	pla	bcc @noStore3	ldx #256	sta <fontWidth,x@noStore3	tyx	;error code to X	pld	ldy #4	jml $e10180	;ToBusyStrip*** end 3-Dec-91;	ENDP;	EXPORT InflateTBInflateTB	PROC*              using E0Vectors;;This does the actual work:;changeFlag	equ fontTemp;	lda newFontWidth	clc	adc newFontWidth	;pad	adc newFontWidth	adc #36;	inc a;	sta newFontWidth	;ADDED 11/17/86 - BHM;	adc maxWidth	asl a	asl a;	sta fontTemp+2	;CHANGED 11/17/86 -	BHM;	lda textBufHeight	cmp newTBHeight	bmi ChangeHeight;current height O.K.:	sta newTBHeight	stz changeFlag	bra GotHeight;ChangeHeight		; 	lda #1	sta changeFlag;GotHeight		; ;"correct" height	in newTBHeight;	lda fontTemp+2	;CHANGED 11/17/86 -	BHM	lsr a	lsr a	lsr a	lsr a	sta newTBRowWords	;possible new textBufRowWords;	lda textBufRowWords	cmp newTBRowWords	bmi ChangeTBRW;textBufRowWords just fine, thank you:	sta newTBRowWords	;"correct" value in	newTBRowWords;;NEXT PART ADDED 11/17/86 - BHM;use old "forced vs. unforced" value as	new one;(it's not elegant, but it's simple)	ldx #256	lda fontWidth,x	sta newFontWidth;END OF ADD-ON	bra GotTBRW;ChangeTBRW		; 	lda #1	sta changeFlag;check to see if the change in width also involves a "forced" width:	ldx #256	lda fontWidth,x	beq NotForced;the old was forced, the new must be also:;	cmp newFontWidth	;(actually, this can be dropped)	bmi ChangeFW	;(ditto);font width is forced, but the old value is ok:	sta newFontWidth	;(ditto)	bra GotFW	;(ditto);;(NOTE:  if it turns out that we must enlarge the textBufRowWords,;then the new fbrExtent - which happens	to be padded - must	have;been larger than the previous fbrExtent, which may have been padded;or forced.  Consequently we can drop the comparison between the new;fbrExtent and the old, forced fbrExtent.  I would do so, except I;haven't quite convinced myself yet . . . .);NotForced		; ;make sure ResetTB knows:	stz newFontWidthChangeFW		; ;(the new value is already in newFontWidth for the change case)GotFW		; ;"Got" either new forced value, old forced value, or 0 indicating unforced;GotTBRW		; ;at this point, newTBRowWords, newTBHeight, and newFontWidth have;all been accounted	for;	lda changeFlag	beq NoChange;	jsl ResetTB;NoChange		; ;	rtl	ENDP;*****************************************************************************;Wednesday, Nov. 12, 1986  1:00 pm;Bennet Marks  x6245;;  GetFontGlobals;* Change History** 7/23/87      	Gary Phipps** Replaced BusyEC with BusyEC4** 30 Dec 88	Steven Glass** Made jmp BusyEC6 into jml BusyEC6 so this can be used in patch.*******************************************************************************GetFontGlobals	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3FGRecPtr	equ RTL2+3;	jsr QDStart;	lda FGRecPtr,s	sta fontTemp	lda FGRecPtr+2,s	sta fontTemp+2;	jsl GetFGS	sta temp2;	jsl GetFL;	jml BusyEC4		ENDP******************************************		**  file TextSubs1		**  contains:		**    ValidChar		**    GetNextChar		**    BumpPen		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;;;*******************************************************************************			                 **              subroutine ValidChar		                 **			                 **		started 3/27/86 or before            **		Bennet Marks  x6245	                 *				                  **			                 **  This subroutine takes the character whose ascii code is in charToDraw     **  and returns its offset/width value (possibly modified) in the acc. and    **  its index into the font's location table in y.  If the character width is **  0, then it will not be modified; otherwise, ValidChar may alter the       **  width on the basis of the font flags, style mods, chExtra, and spExtra.   **  ValidChar also checks to see if the character is "missing"; if it is,     **  the routine returns the o/w value and location table offset of the        **  "missing symbol.	 charToDraw is not altered in any case.	                 **			                 **  ASSUMPTIONS:  SetUpFontInfo, or its equivalent, has been	called.          **			                 **  RETURNS:  (possibly modified) offset/width value in acc.; location table  **  offset in y.			                 **			                 **  NOTES:  ValidChar was broken up into	smaller subroutines	and rewritten on **  or about 2/5/87.	 See documentation of the individual subroutines for     **  more information.		                 **			                 **  Every character seen by the text routines passes through	ValidChar.       **			                 ** 2/12/89	Mensch* Valid char changed to watch for fastfont flag being set, if this flag is set* this routine will simply return the characters width in <A>*******************************************************************************;	EXPORT iValidChariValidChar	PROC*              using E0Vectors;; This tests for fast font routines...; first test the high bit of the font handle to see if it is set,; if it is, we will call the fast text routines!	lda <fastHeadPtr+2	bpl iValidCharOld	; if clear, forget this next stuff	lda <fontFlags	; get the font flags...	and #$0003	; strip the crap off here	beq @stdValue	cmp #$0002	; is it numeric spacing?	bne @StdMono	; use standard monospacing	ldy #'0'	bra @1@stdMono	lda #12	; <widMax	bra @AddExtrasHere@StdValue	ldy <charToDraw	; get the character to draw@1	lda [<fastHeadPtr],y	and #$00FF;; Now test to see if we are going to be using char extra and spExtra, if so add them in; now, if not then just forget it.@AddExtrasHere	bit <fontFlags	bmi @done	; if no extras are needed we are done; now be sure to add the spExtra and charExtra fields NOTE: this is almost the; same as the other addextras routine except for the fact that it uses fastbucket; instead of bucket.	tax	;temp. storage;	lda <fastbucket	clc	adc chExtra	sta <fastbucket	txa	adc chExtra+2	;for chExtra;	ldx charToDraw	cpx #asciiSpace	bne @NotASpace;it's a space:	tax	lda <fastbucket	clc	adc spExtra	sta <fastbucket	txa	adc spExtra+2@NotASpace		; @done	rtl	; and just returniValidCharOld	lda charToDraw;;check for missing character, get appropriate o/w value and	index:	jsl GetCharVals;	bit #lowByte	;check for 0 character width	beq ZeroWidth	;0 width - do not alter;;maybe alter:	ldx fontFlags	beq NoFntFlgMods;;apply font flag mods:	jsl DoFntFlgMods;NoFntFlgMods		; ;take care of style	extra, chExtra, spExtra:	jsl AddExtras;ZeroWidth		; 	rtl	ENDP;*******************************************************************************			                 **              subroutine GetCharVals		                 **			                 **		started 2/5/87	                 **		Bennet Marks  x6245	                 *				                  **			                 **  This subroutine checks the character	whose ascii code is	in the acc.      **  against the current font, so that valid offset/width and	location values  **  can be obtained.	 It returns with the offset/width value	in the acc. and  **  the index from the start of the font's location table to the character's  **  table entry in y.  It particularly checks to see if the character is a    **  "missing" (that is, undefined) character; if it is, the routine returns   **  the offset/width	and index values for the "missing symbol" (the fill-in   **  character at the	end of the font.		                 **			                 **  ASSUMPTIONS:  font information must be in the usual places (this means    **  that SetUpFontInfo has been executed	- at least, most of	it.)             **			                 **  RETURNS:  (1)  offset/width entry in	acc.	                 **            (2)  index into location table in y	                 **			                 **  NOTES:  this used to be part of ValidChar's in-line code; it was factored **  out when it was needed to help calculate the width of the digit 0 for     **  "numerical spacing".		                 **			                 *******************************************************************************;	EXPORT iGetCharValsiGetCharVals	PROC;;character code in acc.:;	cmp firstChar	bmi UseMS	;charToDraw < firstChar;charToDraw >= firstChar . . .	cmp lastChar	bmi GoodRange	;and < lastChar	beq GoodRange	;or = lastChar;charToDraw outside	firstChar-to-lastChar range:UseMS		; 	lda lastChar	inc a	;code for missing symbol;charToDraw in range (and in acc.) OR missing symbol code in acc.GoodRange		; 	sec	sbc firstChar	;subtract off to access arrays	asl a	;(which are 2 bytes	per entry)	tay	lda [owTPtr],y	;offset/width entry	cmp #owMSVal	bne GoodChar;an in-range missing character:	ldy msCodeT2	;use missing symbol	code (*2)	lda [owTPtr],y;GoodChar		; 	rtl	ENDP;;*******************************************************************************			                 **              subroutine DoFntFlgMods		                 **			                 **		started 2/5/87	                 **		Bennet Marks  x6245	                 *				                  **			                 **  This subroutine applies any of the width modifications specifed by the    **  font flags to the offset/width value	of the current character.  It        **  should only be called if the font flags are not all 0 and the width byte  **  of the offset/width entry is not 0; the subroutine does not check for     **  these things.  It expects to find the o/w value in the acc., and returns  **  the modified value in the acc.		                 **			                 **  ASSUMPTIONS:  o/w entry in acc. (width byte not 0); font	flags not all 0. **			                 **  RETURNS:  modified o/w value in acc.		                 **			                 **  NOTES:  this routine was once part of ValidChar.  We have added the       **  "numerical width" option to the font	flags (if this is set, every charac- **  ter is given the	same width as the digit 0).	                 **			                 **  The routine does	not change y.		                 **			                 *******************************************************************************;****************************************	                  **  Feb. 5, 1987  2:45 pm              **	                  ****************************************;	EXPORT iDoFntFlgModsiDoFntFlgMods	PROC;	tax	;temporary storage	lda fontFlags	bit #FxdWdthBit	beq NotFixedWidth;fixed width:	txa	;get back o/w value	and #highByte	;blot out width byte	ora widMax	;replace with widMax	rtl;NotFixedWidth		; 	bit #$0002	beq NotNumWidth; numerical width:	txa	and #highByte	ora digitWidth	rtlNotNumWidth	txa	rtl	ENDP;;*******************************************************************************			                 **              subroutine AddExtras		                 **			                 **		started 2/5/87	                 **		Bennet Marks  x6245	                 *				                  **			                 **  This subroutine modifies the width byte of a character's offset/width     **  value on the basis of extra (the additional character width that comes    **  from style mods), chExtra (which is added to the width of every char-     **  acter that has non-zero width), and spExtra (which is added to the width  **  of the space character).  It expects	to find the o/w value in the acc.    **  (possibly already modified by the font flags), and returns the modified   **  value in the acc.		                 **			                 **  ASSUMPTIONS:  offset/width value in acc.	                 **			                 **  RETURNS:  new offset/width value in acc.	                 **			                 **  NOTES:  AddExtras does not check to see if the width value is 0.          **			                 **  AddExtras does all the bookkeeping for chExtra and spExtra, which are     **  each 4-byte, fixed-point numbers.  (This would be a good	place to handle  **  fractional pixelwidths.)  However, it ASSUMES that the new, modified      **  width is neither	greater than 255 pixels or less than 0.	 (Possibly we    **  should add in a check.  Also, we could cut down on time for strings by    **  computing (chExtra AND chExtra+2 AND	spExtra AND spExtra+2) in            **  SetUpFontInfo - it would tell us quick whether to bother	with these       **  calculations.  But it's probably not worth it.)                           **			                 **  The only character to which spExtra is applied is ascii $20.              **			                 **  The routine does	not alter y.		                 **			                 *******************************************************************************;****************************************	                  **  Feb. 5, 1987  2:45 pm              **	                  ****************************************;	EXPORT iAddExtrasiAddExtras	PROC;	clc	adc extra	;for style;	Export AddExtras2AddExtras2	tax	;temp. storage;	lda bucket	clc	adc chExtra	sta bucket	txa	adc chExtra+2	;for chExtra;	ldx charToDraw	cpx #asciiSpace	bne NotASpace;it's a space:	tax	lda bucket	clc	adc spExtra	sta bucket	txa	adc spExtra+2NotASpace		; 	rtl	ENDP;;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    5:30 PM, 3/30/86	**		******************************************;********************************************************************************			                  **              subroutine GetNextChar		                  **			                  **		started 3/27/86 or before             **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine is used to get successive characters from a     **  string, text block, or Cstring, and to signal (using the	carry bit as a    **  flag) whether any character remained	to be fetched.  The	new character, if **  any, is placed in charToDraw.		                  **			                  **  The "no new characters" condition is	equivalent to textLength = 0 (for     **  strings and text	blocks), or textPtr	pointing to a 0 byte (for Cstrings).  **			                  **  ASSUMPTIONS:  text call information (drawVerb, textPtr, textLength if      **  needed; ordinarily set by DrawString, DrawText, or DrawCString)            **			                  **  RETURNS:			                  **              (1)	carry bit clear if a new character was fetched, carry bit **	set otherwise.		                  **              (2)	new character (if any) in charToDraw	                  **			                  **  ALTERS:			                  **              (1)	textPtr - incremented to point to next character IF a     **	new character was fetched	                  **              (2)	(for strings and text blocks) textLength - decremented IF **	a new character was	fetched	                  **			                  **  If, on the other	hand, there was no new character to be fetched, those     **  values are left alone: for strings and text blocks, textLength is left at  **  0, and textPtr is left pointing 1 byte beyond the last byte of the string; **  for Cstrings, textPtr is left pointing at the 0 byte which terminates the  **  Cstring.			                  **			                  **  NOTES:  every character in a string,	text block, or Cstring passes through **  this subroutine.	 It is the sole place where the differing termination     **  conditions are used.  Consequently it is the best place for a RAM patch to **  handle other kinds of text data structures, or other termination condi-    **  tions (e.g., terminate string on a CR).  It should have a vector entry     **  point.			                  **			                  **  GetNextChar returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/27/86	**		******************************************;	EXPORT iGetNextChariGetNextChar	PROC	lda DrawVerb	cmp #DrawCStrVerb	beq ItsACString;no, it's ordinary string or text block:	lda textLength	beq NoMoreChars	;0 textLength	lda [textPtr]	;get current character	and #lowByte	sta charToDraw	dec textLength	IncLong textPtr	;to point to next character	clc	;to signal presence	of current char.	rtl;ItsACString		; 	lda [textPtr]	and #lowByte	beq NoMoreChars	;0 byte in string	sta charToDraw	IncLong textPtr	clc	rtl;NoMoreChars		; 	sec	;signal no characters remaining	rtl	ENDP******************************************		**  end of GetNextChar	**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    3:40 PM, 3/27/86	**		******************************************;********************************************************************************			                  **              subroutine BumpPen		                  **			                  **		started 3/27/86 or before             **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine increases	the 0-page value currPen by the sum   **  of the character	widths of a sequence of characters.  The sequence can be  **  a string, text block, or Cstring; or	it can be a "final substring", that   **  is, all the characters of a string ("or text block or Cstring"; please in- **  sert this phrase	wherever it seems useful) from some particular character  **  in it to the end	of it.		                  **			                  **  In either case, the first character to be used (not necessarily the first  **  character of the	original string) should be the most recent character      **  fetched and placed in charToDraw by the subroutine GetNextChar.  See       **  ASSUMPTIONS and NOTES below for more	detail.	                  **			                  **  ASSUMPTIONS:  BumpPen assumes that GetNextChar has been called one or more **  times already, so that the first character to be included in the bumping   **  process is already in charToDraw, and textPtr is pointing at the next      **  character (if any); and, for strings	and text blocks, textLength has al-   **  ready been decremented so that it represents the number of characters      **  left (that haven't already been fetched by GetNextChar).  (see NOTES       **  below)			                  **			                  **  BumpPen calls GetNextChar and ValidChar, so font and text information      **  used by those subroutines must be set up (see documentation for each).     **			                  **  Strings or substrings ("or etc.") of	length 0 should never make it to this **  subroutine; the calling routine should screen them out on the basis of its **  previous call to	GetNextChar.  (however, the number of remaining charac-   **  characters, not yet fetched by GetNextChar, may be 0)	                  **			                  **  RETURNS:  new value in currPen.		                  **			                  **  ALTERS:  textPtr	and (for strings and text blocks) textLength.             **			                  **  NOTES:  in the abstract above, a big	deal seems to have been made about    **  BumpPen's ability to handle "final substrings" as well as complete         **  strings.  This was mentioned explicitly because BumpPen is frequently used **  to "finish off" the updating of currPen after it has been partially up-    **  dated by characters handled by PutChar.	                  **			                  **  However, the truth of the matter is that, because of the	way GetNextChar   **  works, NONE of the QD II text routines can tell the difference between a   **  string and a "final substring".  If textPtr and (when used) textLength are **  kept up to date - GetNextChar does this - any final substring looks just   **  like a string.			                  **			                  **  BumpPen is only used with strings, text blocks, and Cstrings.  It does not **  work with individual characters (although it will handle	strings of length **  1 just fine).			                  **			                  **  BumpPen returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/27/86	**		******************************************;	EXPORT iBumpPeniBumpPen	PROC*              using E0Vectors;NextChar		; 	jsl ValidChar	and #lowByte	;get character width	clc	adc currPen	sta currPen;	jsl GetNextChar	bcc NextChar	;if any;no more:	rtl	ENDP******************************************		**  end of BumpPen		**		******************************************;;                copy text/TextSubs2******************************************		**  file TextSubs2		**    CalcDrawStatus		**    TextAndMinRect		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    3:00 PM, 3/30/86	**		******************************************;********************************************************************************			                  **              subroutine CalcDrawStatus	                  **			                  **		started 3/28/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine determines whether it is appropriate to draw    **  anything into the current grafport's pixelmap.  Two conditions are         **  checked:  (1)  is the pen visible?  (2)  is the minRect non-null?  If the  **  answers to both those questions are yes, CalcDrawStatus returns with the   **  carry bit cleared, meaning drawing can be done.  Otherwise, no drawing can **  be done; the carry is set.  The subroutine also sets (by	a call to         **  makeMinRect) the	minRect based on the current grafport.	                  **			                  **  ASSUMPTIONS:  the subroutine requires the usual information about the      **  current grafport	to be on 0-page.  This can be insured by calls to         **  PortLoc2ZP and SetUpPortRegions.		                  **			                  **  RETURNS:  carry bit clear if drawing	is appropriate (i.e., pen visible     **  and minRect non-null), carry bit set	otherwise. Overflow set if ok to      **  use fasttext routines		                  **			                  **  ALTERS:  minRect	(and anything else changed by a call to	makeMinRect).     **			                  **  NOTES:  CalcDrawStatus returns via an RTL.	                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/28/86	**		** 2/24/89	Mensch* Modified to support fasttext routines this now sets the overflow flag if* MinRect can be safely relied upon to be a "safe" drawing area******************************************;	EXPORT iCalcDrawStatusiCalcDrawStatus	PROC;*              USING E0Vectors*              USING CoreData;	ldy #O_pnVis	lda [portRef],y	bmi PenInvisible;pen visible, so check minRect:	lda #(-maxInt)	;set up max rectangle in minRect	sta minRect+O_V1	sta minRect+O_H1	lda #maxInt	sta minRect+O_V2	sta minRect+O_H2;	jsl MakeMinRect	bcs NullRect; pen visible, rect not null; signal o.k. to draw:; Also test regionPointers A and B for rectangular reqions, If they are; rectangular set the overflow flag	lda [<rgnPtrA]	ora [<rgnPtrB]	cmp #10	; are they both rects???	bne NotRects;; 2/24/89 Mensch; Add checks for grafport fields, fgcolor bgcolor and txMode; 3/21/89 and txFace	ldy #o_txMode	lda [<portRef],y	; combine mode and forcolor	and #$FFFB	; strip off bit 3...	ldy #o_FGColor	; offset to foreground color field	ora [<portRef],y	; combine mode and forcolor	ldy #o_txFace	ora [<portRef],y	; also take into account the text face...	bne NotRects	; are they both zero???	ldy #o_BGColor	lda [<portRef],y	cmp #$FFFF	beq @cont	cmp #$0003	beq @cont	cmp #$000F	bne NotRects@cont	lda <portSCB	and #$0080	beq NotRects	sep #$40	; set overflow	clc	; clear carry	rtlNotRects	sta >$FF3000	; trigger analyser	clv	; clear rect flag	clc	; we got a minrect	rtl;PenInvisible		; 	sec	;to signal not O.K.NullRect		; ;carry already set by makeMinRect	rtl	bra NotRects	ENDP******************************************		**  end of CalcDrawStatus	**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    10:00 PM, 5/13/86	**		******************************************;********************************************************************************			                  **              subroutine TextAndMinRect	                  **			                  **		started 3/28/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine calculates the intersection of the "text rec-   **  tangle" and the current minRect, and	replaces minRect with the result.  If **  the result is a null rectangle, the carry bit is set on return; otherwise  **  the carry is cleared.		                  **			                  **  The "text rectangle" is the smallest	rectangle that completely encloses a  **  graphical text object and its background (by "graphical text object", we   **  mean character, string, text block, or Cstring).  It is represented in     **  local coordinates.  In this subroutine, we do not start with the text      **  rectangle as a given, but calculate it on the fly from leftExtent,         **  rightExtent, startBufPen, and bufPen.  The conversion to	local coordinates **  is also done on the fly.		                  **			                  **  ASSUMPTIONS:  TextAndMinRect expects:	                  **			                  **              (1)	a minRect on 0-page	(usually set by a call to             **	CalcDrawStatus, which calls MakeMinRect)                  **              (2)	startBufPen, and buffer-to-local translation values       **	(usually set by a call to SetUpBufInfo)	                  **              (3)	bufPen, leftExtent,	and rightExtent (usually set by       **	SetUpBufInfo and altered by 1 ore more calls to PutChar)  **              (4)	chHeight, generally	from SetUpFontInfo (we may wind up    **	using something other than chHeight eventually; see NOTE  **	embedded in code below)	                  **			                  **  RETURNS:  (1)  carry bit clear if the intersection is non-null, carry set  **                 otherwise		                  **            (2)  resulting rectangle in minRect on 0-page	                  *	 *			                  **  NOTES: TextAndMinRect returns via an	RTL	                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/28/86	**		**    addded a missing RTL (of all	**    things!) - 5/13/86, BHM	**		******************************************;	EXPORT iTextAndMinRectiTextAndMinRect	PROC;;find left boundary	of text rectangle (first in buffer coordinates):	lda leftExtent	cmp startBufPen	;we want the smaller	bmi LeftExtOK	;it's leftExtent	lda startBufPen	;no, it's startBufPenLeftExtOK		; ;;shift to local coordinates	clc	adc hBufToLoc;;compare against corresponding minRect length	cmp minRect+O_H1	;we now want the larger	bmi MRH1Larger	;minRect.H1 is larger	sta minRect+O_H1	;no it's not, so replace itMRH1Larger		; ;;the rest is very much the same;	lda #1	;the top row, in buffer coordinates	clc	adc vBufToLoc	;switch to local coordinates	cmp minRect+O_V1	;and compare	bmi MRV1Larger	sta minRect+O_V1	;replace if necessaryMRV1Larger		; ;	lda rightExtent;For rightExtent, we must add 1 to maintain the QD distinction between pixels;and rectangles (the enclosing rectangle always has a right	boundary 1 greater;than the pixel it encloses; same for bottom boundary, but not left or top).;bufPen is, serendipitously, already 1 greater than the rightmost pixel of;the character and its background, because it is the starting pen position;for the next character	inc a	cmp bufPen	;we want the larger	of these two	bpl rightExtOK	lda bufPenrightExtOK		; ;;shift to local	clc	adc hBufToLoc	cmp minRect+O_H2	;compare to minRect	- want the smaller	bpl MRH2Smaller	;minRect.H2 smaller	sta minRect+O_H2	;no, so replace itMRH2Smaller		; ;;H2 should be strictly larger than H1	lda minRect+O_H1	cmp minRect+O_H2	bmi HOK	;horizontal length ok	brl NullRect	;no, it's not;HOK		; ;	lda chHeight	;bottom row in buffer coord.'s	inc a	;for the same reason as before;[NOTE:  this chHeight may be embarrassing later when we have style mods that;change the nominal	buffer size.  We may want a new 0-page location to hold a;mutable value]	clc	adc vBufToLoc	;local coord.	cmp minRect+O_V2	bpl MRV2Smaller	;minRect.V2 fine	sta minRect+O_V2	;or replace itMRV2Smaller		; ;;V2 should be strictly greater than V1	lda minRect+O_V1	cmp minRect+O_V2	bmi VOK	;vertical ok	brl NullRect	;nuh-uh!;VOK		; ;	clc	;to signal non-null	intersection	rtl;NullRect		; 	sec	;or not	rtl	ENDP******************************************		**  end of TextAndMinRect	**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;;                copy text/TextSubs3******************************************		**  file TextSubs3		**    CalcTextBounds		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    9:45 AM, 4/15/86	**		******************************************;********************************************************************************			                  **              subroutine CalcTextBounds	                  **			                  **		started 3/28/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine calculates several pointers, offsets, and other **  values which are	used by the subroutine BlowItUp to determine which        **  chunk of the text buffer needs to be	transferred to what	piece of the      **  destination pixelmap (BlowItUp is the routine which does	that transfer,    **  also in the process expanding the 1 bit/pixel text buffer information      **  into the 2 bit/pixel or 4 bit/pixel information needed by the destina-     **  tion - hence the	name).		                  **			                  **  ASSUMPTIONS:  CalcTextBounds requires the following:	                  **			                  **              (1)	the usual current grafport information on 0-page; in      **	particular, width, boundsRect, imageRef, and portSCB      **              (2)	similar information	for the text buffer	- bufRowBytes     **	and bufPtr		                  **              (3)	the results of TextAndMinRect placed in	0-page's minRect  **			                  **  RETURNS:  the subroutine returns the	following:	                  **			                  **              (1)	tbRowPtr - a 4-byte	pointer to the start of the first     **	(i.e., highest) text buffer row which is to be trans-     **	ferred to the destination pixelmap (that is, the row      **	corresponding to the top of our new minRect)              **			                  **              (2)	tbStartByte - the offset, in bytes, from tbRowPtr to the  **	first text buffer word containing any image bits which    **	are to be transferred into to be transferred into the     **	destination pixelmap (that is, the word	containing the    **	pixel corresponding	to the left side of	minRect).  This   **	will always be even.	                  **			                  **              (3)	pmRowPtr - a 4-byte	pointer to the start of the row in    **	the destination pixelmap corresponding to the top of      **	minRect (see tbRowPtr).	                  **			                  **              (4)	pmStartByte - the offset, in bytes, from pmRowPtr to the  **	beginning of the first PIXELWORD of the	destination       **	pixelmap into which	character image pixels are to be      **	transferred.  A pixelword is a collection of 16 contig-   **	ous pixels, aligned	to some starting point (in this case, **	pmRowPtr).  pmStartByte will always be divisible by 4 in  **	640 mode, 8 in 320.		                  **			                  **              (5)	numOfWords - the number of distinct words in each text    **	buffer row which contain character image pixels which     **	are to be transferred into the destination.  IMPORTANT    **	NOTE:  this is a "0-based counter"; that is, a value of   **	0 means 1 word to be transferred, 1 means 2 words, etc.   **			                  **              (6)	rowCounter - the number of rows to be transferred to the  **	destination.  IMPORTANT NOTE:  this is also a 0-based     **	counter.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/30/86	**    4/15/86 - changed to allow cross-	**    bank boundaries - BHM	**		******************************************;	EXPORT iCalcTextBoundsiCalcTextBounds	PROC;;rowCounter:	lda minRect+O_V2	;rect coordinate;bottom (and right)	boundaries of enclosing rectangles are always 1 more than;the most extreme pixel they enclose, so to get pixel coordinate we decrement	dec a	;(a lot of talk for	a dumb DEC)	sec	sbc minRect+O_V1	sta rowCounter;;pmRowPtr:;we need multiples of pixelmap width to	calculate pointer;	pushlong #0	pei width	;pixelmap width in bytes	lda minRect+O_V1	;first row	sec	sbc boundsRect+O_V1	;shift to global coordinates	pha;	_Multiply;	pla	;result low word	sta temp	pla	;high word	sta temp+2;	lda imageRef	;pointer to dest. start	clc	adc temp	sta pmRowPtr	lda imageRef+2	adc temp+2	sta pmRowPtr+2;;tbRowPtr:;similar to pmRowPtr, mutatis mutandis;	pushlong #0	pei bufRowBytes	lda minRect+O_V1	sec	sbc vBufToLoc	;this gets us buffer coord.	dec a	;dec, because buffer rows start at 1	pha;	_Multiply;(in the future we may wish to replace these multiplies with in-line routines;optimized for small second arguments.	In particular, this	last one is;usually 0 - whenever the top of the character fits in the destination;pixelmap);	pla	sta temp	pla	sta temp+2;	lda bufPtr	clc	adc temp	sta tbRowPtr	lda bufPtr+2	adc temp+2	sta tbRowPtr+2;;now hone in on the	boundary words;pmStartByte:;	lda minRect+O_H1	;minRect.H1, in local	sec	sbc boundsRect+O_H1	;change to global;we now have pixel position	lsr a;for 320, that LSR gets us from number of pixels to number of bytes;(2 pixels/byte in 320) -  we'll need another for 640	bit portSCB-1	bmi mode640;mode320:	and #first13bits	;round down to nearest multiple of 8	bra GotPMSBmode640		; 	lsr a;pixel position now	divided by 4 altogether to get number of bytes -;(4 pixels/byte in 640)	and #first14bits	;round down to nearest multiple of 4;GotPMSB		; ;got pixelmap startbyte	sta pmStartByte;;tbStartByte:	lda minRect+O_H1	;starting pixel, local	sec	sbc hBufToLoc	;buffer coordinate thereof	lsr a	lsr a	lsr a	lsr a	sta temp	;this would be "tbStartWord"	asl a;	sta tbStartByte;;numOfWords:	lda minRect+O_H2	;right rect boundary	dec a	;ending pixel, local	sec	sbc hBufToLoc	;buffer coordinate	lsr a	lsr a	lsr a	lsr a;this is "tbEndWord", but we just need it for a calculation	sec	sbc temp	;subtract "tbStartWord"	sta numOfWords	rtl	ENDP******************************************		**  end of CalcTextBounds	**		******************************************;;                copy text/TextSubs4******************************************		**  file TextSubs4		**    SetUpFontInfo		**    SetUpBufInfo		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;;;  This version of SetUpFontInfo goes into the 1.1 ROM;********************************************************************************			                  **              subroutine SetUpFontInfo		                  **			                  **		started 3/30/86 or before             **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine gets and/or calculates certain font-related     **  information from	the current font (the one whose handle is in the current  **  grafport).If the current font is a fastfont, this routine uses the acc     ** on entry to determine which font info to set up. If you pass a zero, it     ** will pass you the realfont info, if you pass a -1 it will give you fastfont ** info on dpage.			                  **  ASSUMPTIONS:  only that portRef points to a valid grafport, and that the   **  grafport's font field points to a valid font.                              **			                  **  RETURNS:			                  **              (1)	4-byte pointers:		                  **			                  **              fontRecPtr - to the start of the font record	                  **              strikePtr - to the start	of the font strike	                  **              owTPtr - to the start of	the font offset/width table           **              locTPtr - to the start of the font location table              **              locTP2Ptr - 2 bytes into	the location table (trust me, it's    **              useful)		                  **			                  **              (2)	2-byte values:		                  **			                  **              firstChar - ASCII code of the font's first defined character   **              lastChar - ASCII code of	the font's last defined character     **              msCodeT2 - index value for the font's "missing symbol", given  **              by:			                  **	    msCodeT2 = 2 * (lastChar + 1 - firstChar)             **			                  **              kernMax - the font's maximum leftward kern, represented as a   **              negative number (or 0)		                  **              chHeight - the font's character height                         **              ascent - the font's ascent                                     **              descent - the font's descent                                   **              fbrExtent - (see external doc. for description)                **              rowBytes - width of the font strike, in bytes - must be even   **              (rowBytes = 2 * textRowWords)	                  **			                  **  NOTES:  DBR is preserved.		                  **			                  **  SetUpFontInfo returns with an RTL.		                  **			                  **			                  **  Change History:			                  **			                  **  This version of SetUpFontInfo was modified on 2/6/87 for	use in the 1.1    **  ROM.  It has absorbed the patch replacing fRectMax with fbrExtent, and it  **  includes the patch which calculates digitWidth.  It also	no longer locks   **  the font.			                  **			                  **  13 Oct 88	Sue Dumont		                  **			                  **  Version 1.02  -- Apple IIGS font header contains an additional field.  This**  is highOwTLoc, the high word of the offset to the offset/width table.      **			                  *** 2/15/89	Mensch* * Added fastfont info handling stuff...		                  ********************************************************************************;****************************************	                  **  Mar. 10, 1987  11:30 am            **	                  ****************************************;	EXPORT iSetUpFontInfoiSetUpFontInfo	PROC;*              USING Coredata*              using E0Vectors;;(the two values aren't necessarily the same - we've just replaced the;text routine's use of fRectMax with fbrExtent, which is a more useful;measure.  Probably	we should drop the 0-page location name	fRectMax;altogether.);	tax	; place flag in <X> for a second	phb;;THE FOLLOWING CHANGED FROM A CALL TO DEREFANDLOC - 2/7/87;; Modified 2/12/89 to load new info if the fastfont is being used... Mensch;; Modified 3/21/89	Mensch; Added spExtra/charExtra and fontflags to this load...	ldy #(O_font+2)	lda [portRef],y	;font handle high word	bmi @FastFont	brl standardFont	; if high bit clear we are using a standard font;;;@FastFont	cpx #-1	; is it a negative 1???	bne loadStdData	; if not, load the standard data	jsl MakeFastFontInfo ; else load the good dataFastSetupCont	ldy #O_spExtra	lda [portRef],y	sta spExtra	iny	iny	lda [portRef],y	sta spExtra+2	ldy #O_chExtra	lda [portRef],y	sta chExtra	iny	iny	lda [portRef],y	sta chExtra+2;	ldy #o_txMode	lda [<portRef],y	; combine mode and forcolor	sta <FastMode	ldy #O_fontFlags	lda [portRef],y	and #$0003	sta fontFlags;	ora chExtra	; now make sure spextra/fontflags and 	ora chExtra+2	; char extra are zero	ora spExtra	ora SpExtra+2	bne @UseExtra	lda #$C000	sta <FontFlags	plb	rtl@UseExtra	lda <fontflags	bne @cantuse	; damn we got monospacing bullshit; now test chExtra too see if it is too large (it can't be >= $10000)	lda chExtra+2	bne @cantuse; now test to see if spExtra is set, if so see if too large (it can't be >=$40000)	lda spExtra+2	cmp #4	bge @cantUse; otherwise, just go ahead and use it...	lda #$4000	sta <fontFlags	lda #half	sta fastbucket	; fastfonts use a different bucket than slowfonts;	plb	; suck off the data bank	rtl	; and just return...;; 4/24/89 Mensch; If we get to this point the port ref can contain either a fastfont handle or a; standard font handle. If its the fast font handle we must deref a few levels,; if not we should just rejoin the standard code as it was.@cantuse	ldy #(O_font+2)	lda [portRef],y	;font handle high word	bmi LoadStdData	; we have an actual fastfont in the port	brl SF0005	; else, just finish setting up the slow way0o_FFOldFont	equ $0100loadStdData	sta temp+2	; get the handle to the fastfont stuff	ldy #o_font	lda [portRef],y	sta temp	lda [temp]	; and deref it...	sta fontHeadPtr	ldy #2	lda [temp],y	sta fontHeadPtr+2;	ldy #o_oldFontHandle ; offset to the old font..	lda [fontHeadPtr],y	; get the old font handle	sta temp	ldy #o_oldFontHandle+2	lda [fontHeadPtr],y	sta temp+2	; set temp to be the old font handle	bra SF0010	; and branch into standard font stuff	ShowFastROMFont	ldx #512	; get the fast ROM font off dpage	lda <FastRomFont,x	; see if fast ROMFont exists	ora <FastRomFont+2,x	bne SFRF0005	ldy #o_Font+2	lda [<portRef],y	bra SF0005	; call back the standard stuff now...SFRF0005;	brk 00	lda <FastRomFont,x	; copy the fast font handle to zpage	sta <FastHeadPtr	lda <FastRomFont+2,x	sta <FastHeadPtr+2	jsl MakeFastFontInfo2 ; else load the good data	brl FastSetupCont	; and finish the setup...standardFont;; 3/21/89	Mensch; Changed for invisiblefastfont. This will test to see if we are using the systemfont now, if; we are it will use the fastfont instead	cpx #-1	; see if we want the fast font even...	bne SF0005	; if not, load the standard data	cmp #^SystemFont	bne SF0005	; if not the ROM font then forget it	sta temp+2	; save this for a sec...	dey	dey	lda [portRef],y	cmp #SystemFont	bne SF0006	; if these are both not equal then not ROM font; else, show the fastromfont now!	brl ShowFastRomFont ; else load the fast rom font stuff...SF0005	sta temp+2	dey	dey	lda [portRef],ySF0006	sta temp;SF0010	lda [temp]	sta fontHeadPtr	ldy #2	lda [temp],y	sta fontHeadPtr+2;;END OF CHANGE - BHM  x6245;	lda [fontHeadPtr]	asl a	clc	adc fontHeadPtr	sta fontRecPtr	lda fontHeadPtr+2	bcc @NoCarry	inc a	@NoCarry	sta fontRecPtr+2;;the next 2 are first guesses, to be modified by arithmetic	further down;	sta strikePtr+2	sta owTPtr+2;	pei fontHeadPtr+1	; set dbr to access	font	plb	plb;	ldx fontRecPtr;	lda |FMinChar,x	MacSwitch	sta firstChar;	lda |FMaxChar,x	MacSwitch	sta lastChar;	inc a	sec	sbc firstChar	asl a	sta msCodeT2;	lda |FMaxWd,x	MacSwitch	sta widMax;	lda |FBBOX,x	MacSwitch	sta kernMax;;FETCHING OF FRECTMAX DROPPED HERE - 2/7/87, BHM  x6245;;CALCULATION OF FBREXTENT MOVED HERE WHEN WE DISCOVERED THAT THERE;WERE 1.0 FONTS OTHER THAN THE ORIGINAL	ROM FONT (namely, Dan's;controls font) - 3/10/87, BHM;	lda #V0100	;version 1.0	ldy #o_Version	cmp [fontHeadPtr],y	;actual version	bpl ItsVersion1	;or less (if there were any such);version > 1.0	ldy #o_FBRExtent	lda [fontHeadPtr],y	sta fbrExtent	bra GotFBRX;ItsVersion1		; ;need a reasonable guess for fbrExtent:	ldy #FmaxWd	lda [fontRecPtr],y	ldy #FBBDX	cmp [fontRecPtr],y	;fRectMax	bpl MaxWdBigger;fRectMax bigger - use it instead:	lda [fontRecPtr],yMaxWdBigger		; 	clc	adc kernMax	;add kernMax to the	soup;GotFBRX		; ;stir later	sta fbrExtent;;END OF CALCULATION	OF FBREXTENT;*********************************************************************** Version 1.02 - SMD      13 Oct 88**                the following is highOwTLoc, the high word of *                the offset to the offset/width table.*** 30 Oct 88	Steven Glass** (Moved Version102 variable from in line to direct page.)**********************************************************************	ldy #o_Version	;check the version number	lda [fontHeadPtr],y	cmp #V0102	bpl Vers102	stz Version102	;version less than 1.02	bra GetHeight	Vers102	lda #1	;Version 1.02 or greater	sta Version102	ldy #12	lda [fontHeadPtr],y	sta owTPtr+2	;for now, keep #words in highOwTLoc here	GetHeight	lda |FBBDY,x	MacSwitch	sta chHeight;	lda |FAscent,x	MacSwitch	sta ascent;	lda |FDescent,x	MacSwitch	sta descent;	lda |FLeading,x	MacSwitch	sta leading;	lda |FLength,x	;owTLoc in WORDS	MacSwitch	asl a	;now in BYTES	sta temp	lda Version102	;check if version	beq NotV102	lda owTPtr+2	rol a	clc	adc fontRecPtr+2	sta owTPtr+2	NotV102	lda temp		clc	adc #FLength	bcc NoCarry1	inc owTPtr+2NoCarry1		; 	clc	adc fontRecPtr	bcc NoCarry2	inc owTPtr+2NoCarry2		; 	sta owTPtr;;now calculate loc table pointers from whatever's handy:	lda owTPtr+2	sta locTPtr+2	lda msCodeT2	clc	adc #4	sta temp	lda owTPtr	sec	sbc temp	sta locTPtr	bcs NoBorrow	dec locTPtr+2NoBorrow		; 	lda #FStrike	clc	adc fontRecPtr	sta strikePtr	bcc NoCarry3	inc strikePtr+2NoCarry3		; ;	lda |FRaster,x	;width of strike in	words	MacSwitch	asl a	;now bytes	sta rowBytes;	ldy #O_fontStyle	lda [fontHeadPtr],y	eor #allBitsOn	ldy #O_txFace	and [portRef],y	sta txFace;	stz extra	bit #boldBit	beq NotBold	inc extraNotBold		; ;	ldy #O_spExtra	lda [portRef],y	sta spExtra	iny	iny	lda [portRef],y	sta spExtra+2;	ldy #O_chExtra	lda [portRef],y	sta chExtra	iny	iny	lda [portRef],y	sta chExtra+2;	ldy #O_fontFlags	lda [portRef],y	sta fontFlags;	lda #half	sta bucket;;ADDED 2/6/87:;	lda fontFlags	and #numWdthBit	beq NotNumWidth	;so don't calculate digitWidth;calculate digitWidth:	lda #asciiZero	jsl GetCharVals	;get o/w value of digit 0	and #lowByte	;isolate width	sta digitWidth;NotNumWidth		; ;;END OF ADDITION - BHM  x6245;	plb	rtl	ENDP******************************************		**  end of SetUpFontInfo	**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    2:30 PM, 4/23/86	**		******************************************;;********************************************************************************			                  **              subroutine SetUpBufInfo		                  **			                  **		started 3/30/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine gets and/or calculates certain information      **  regarding the text buffer to be used	by QD II text-drawing routines.       **			                  **  ASSUMPTIONS:			                  **              (1)	textBufHandle, textBufRowWords, and textBufHeight on      **              0-page		                  **              (2)	the usual 0-page grafport information, including portRef  **              and boundsRect		                  **              (3)	SetUpFontInfo has been called (we need fRectMax)          **              (4)	currPen has been set.  This is the horizontal pen posi-   **              tion	in the destination pixelmap where character drawing is to **              start, expressed in local coordinates (you can think of it as  **              the "current pen position", except that it may have been ad-   **              justed to account for characters in a string	that would, in    **              drawing, fall to the left of the current visible region).      **			                  **  RETURNS:			                  **              (1)	4-byte pointers:		                  **              bufPtr - to the start of	the text buffer	                  **			                  **              (2)	2-byte values:		                  **              bufRowBytes - buffer width in bytes; must be	even              **              (bufRowBytes = 2 * textBufRowWords)	                  **              hBufToLoc - horizontal translation value from buffer coord-    **              inates to local coordinates	                  **              vBufToLoc - vertical translation from buffer	to local          **              startBufPen - a good starting pixel position	(horizontal) in   **              the text buffer for the transfer of character images from the  **              font	strike.  "Good", here, subsumes the following properties: **			                  **              (a)	startBufPen has the	same pixel-in-word alignment (i.e.,   **              has the same last 4 bits) as the destination	pen expressed in  **              GLOBAL coordinates (that	is, currPen transformed from local    **              to global).  This insures that BlowItUp (the	buffer-to-destin- **              ation transfer subroutine) won't have to rotate buffer image   **              words for use in the destination.	                  **              [yeah, I know that's verbose, but I didn't understand the      **              the idea myself for the LONGEST time, so I'm showing off]      **			                  **              (b)	startBufPen is large enough (i.e., the "buffer pen"       **              starts far enough into the buffer) that neither kerning nor    **              the vagaries of PutChar (the strike-to-buffer transfer rou-    **              tine) will involve memory words outside the text buffer.       **			                  **              bufPen - a copy of startBufPen.  bufPen will	be updated by     **              calls to PutChar; startBufPen will be left alone.  Both values **              are needed later.		                  **			                  **  NOTES:  both textBufRowWords and textBufHeight are 1-based counters [check **  this].			                  **			                  **  SetUpBufInfo does NOT clear the buffer; ClearBufPart is used for that.     **			                  **  The "safety margins" built into this	subroutine and SizeTextBuffer do not  **  take into account spExtra, charExtra, style mods, etc.; they may have to   **  be changed when those features are implemented.	                  **			                  **			                  **  SetUpBufInfo returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/31/86	**		******************************************;	EXPORT iSetUpBufInfoiSetUpBufInfo	PROC;*              USING Coredata;	ldx textBufHandle+2	lda textBufHandle	;handle to buffer	jsr TextDeref	;now pointer to locked buffer	stx bufPtr+2	sta bufPtr;	lda textBufRowWords	asl a	sta bufRowBytes;;we want to align buffer pen position (horizontal) and destination pixelmap;position (horizontal, and in GLOBAL coordinates) with respect to pixel;position within pixelmap -;get destination pixelmap horizontal pen position, in local:	lda currPen;switch to global:	sec	sbc boundsRect+O_H1;	and #last4Bits	;pixel position within pixelword	sta temp;****  SUBROUTINE CHANGED 3/10/87;;  The calculation of "fontSlop" (the current fbrExtent, including style;  mods et al) has been pushed off to the new subroutine CalcSlop, which;  is called before	SetUpBufInfo, and which hides the slop on the third;  0-page for SetUpBufInfo to find.;;so go fetch:	ldx #512	lda fontSlop,x;****  END OF THAT CHANGE - BHM  x6245;	clc	adc #$0020	;for round-off and algorithm;	and #first12Bits	;occasion of possible round-off error	ora temp	;align buffer pen to dest. pen	sta startBufPen	sta bufPen;;get some translation values:;	lda currPen	;pnLoc.H	sec	sbc startBufPen	sta hBufToLoc	;horizontal translation from buffer;		;coordinates to local coordinates	ldy #(O_pnLoc+O_V)	lda [portRef],y	;pnLoc.V	sec	sbc ascent;HERE IT COMES AGAIN	dec a;DID YOU BLINK?	sta vBufToLoc	;vertical translation;;;the following assignments may seem backwards, but they guarantee valid;leftExtent and rightExtent as soon as a pixel is put down,	as well as;enabling us to check easily on a null image (no pixels put	down) condition.;	lda #maxInt	sta leftExtent	lda #(-maxInt)	sta rightExtent;	rtl	ENDP******************************************		**  end of SetUpBufInfo	**		******************************************;;                copy text/TextSubs5******************************************		**  file TextSubs5		**    SizeTextBuffer		**    GetTextHandle		**		******************************************;;||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    5:00 PM, 4/1/86	**		******************************************;********************************************************************************			                  **              subroutine GetTextHandle		                  **			                  **		started 4/1/86 or before              **		Bennet Marks  x6245	                  **			                  **  ABSTRACT:  this subroutine allocates	a block of space for the QD II text   **  buffer, and places a handle to this block in the 0-page global location    **  textBufHandle.  The buffer block itself is set to some nominal amount of   **  space, and is in	this form basically	useless; proper sizing (and clearing) **  of the buffer is	done later by the subroutine SizeTextBuffer.              **			                  **  GetTextHandle should be called when QD II is initialized, and must be      **  called before any call to SizeTextBuffer, which expects to find a valid,   **  if puny, textBufHandle.		                  **			                  **  ASSUMPTIONS:  only that the memory manager is active.	                  **			                  **  RETURNS:  if the	call to the memory manager returns no error, this sub-    **  routine sets textBufHandle and clears the carry bit.  If	there was a mem-  **  ory manager error, then the carry is	set and the error code passed back    **  unchanged in the	acc.  (in that case, textBufHandle will	not be set).      **  The only expected error is MFullErr (memory full error).	                  **			                  **  NOTES:  currently GetTextHandle insists that the text buffer be entirely   **  in one bank.  This will probably be relaxed later.	                  **			                  **  GetTextHandle returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 4/1/86		**    changed to permit buffer to	**    stradle bank boundaries -	**    BHM, 4/21/86		**		******************************************;	EXPORT iGetTextHandleiGetTextHandle	PROC;	pushlong #0	;for result	pushlong #15	;a token amount	lda UserID	pha	pea 0	pushlong #0	;I assume this is not used;	_NewHandle	bcc NoMemError;memory error:	plx	plx	;clear stack;note carry set and	error code in acc. still	rtl	;so just return;;NoMemError		; 	pla	sta textBufHandle	pla	sta textBufHandle+2;note carry clear still	lda #0	;so clear acc.	rtl	;and just return	ENDP******************************************		**  end of GetTextHandle	**		******************************************;;                copy text/TextSubs6******************************************		**  file TextSubs6		**    ClearBufPart		**    CleanUpBuffer		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    4:45 PM, 5/9/86	**		******************************************;********************************************************************************			                  **              subroutine ClearBufPart		                  **			                  **		started 3/31/86 or before             **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine zeros out	every word of the text buffer from    **  leftExtent to rightExtent, along every row (from 1 to textBufHeight).      **  Note that leftExtent = 0 refers to the first word in a row, but that the   **  rows themselves are counted starting	from 1.  To clear the entire buffer,  **  set leftExtent =	0 and rightExtent =	bufRowWords - 1.	                  **			                  **  ASSUMPTIONS:  textBufHeight (usually	set by SizeTextBuffer) and bufPtr     **  and bufRowBytes (both usually set by	SetUpBufInfo) are on 0-page.          **  leftExtent and rightExtent are defined, and measured in words.             **			                  **  ALTERS:  ClearBufPart uses numOfWords, currBufByte, bufByte, wordCounter,  **  and rowCounter for bookkeeping.		                  **			                  **  NOTES:  throughout most of the QD II	text routines, leftExtent and         **  rightExtent are measured in PIXELS.	They are initialized by SetUpBufInfo, **  altered by PutChar, and used to get text boundaries.  Before they are      **  used here, they must be "boiled down" to words (i.e., divided by 4 and     **  rounded down).			                  **			                  **  DBR is preserved.		                  **			                  **  ClearBufPart returns with an RTL.		                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 3/31/86	**    changed to handle bank boundaries;	**    doc. not up to	date yet - BHM,	**    4/21/86		**		**    changed to use	chHeight in place	**    textBufHeight - doc. STILL not up	**    to date - BHM,	5/9/86	**		******************************************;	EXPORT iClearBufPartiClearBufPart	PROC	phb;	lda leftExtent	;words	asl a	;now bytes	sta temp	clc	adc bufPtr	sta tbRowPtr	lda bufPtr+2	bcc @NoCarry	inc a@NoCarry	sta tbRowPtr+2	pei tbRowPtr+1	;set DBR to match current row position	plb	plb;	lda rightExtent	asl a	sec	sbc temp	sta numOfBytes;	lda chHeight	sta rowCounter;NextRow		; 	lda #0	ldy #0;NextWord		; 	sta (tbRowPtr),y;	cpy numOfBytes	beq CheckRows	;this row done;no, it isn't:	iny	iny	bra NextWord;CheckRows		; 	dec rowCounter	beq BufCleared	;all rows cleared;bump pointer for next row:	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry	inc tbRowPtr+2	pei tbRowPtr+1	;reset DBR if necessary	plb	plbNoCarry		; 	bra NextRow;BufCleared		; ;please note it is only cleared along the columns specified	plb	rtl	ENDP******************************************		**  end of ClearBufPart	**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    4:10 PM, 4/4/86	**		******************************************;********************************************************************************			                  **              subroutine CleanUpBuffer		                  **			                  **		started 4/4/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine zeroes out all words in the text buffer that    **  may have been written into by PutChar (or any other routine that may write **  into the text buffer, and observes the right bookkeeping	protocols).       **			                  **  ASSUMPTIONS:  textBufHeight (usually	set by SizeTextBuffer) and bufPtr     **  and bufRowBytes (both usually set by	SetUpBufInfo) are on 0-page.          **  leftExtent and rightExtent are the leftmost pixel and rightmost pixel pos- **  sitions, respectively, that have been "dirtied" by PutChar or some similar **  routine; if no pixel in the text buffer has been touched, then leftExtent  **  is greater that rightExtent (these conditions are insured by a call to     **  SetUpBufInfo, followed by 0 or more calls to PutChar).	                  **			                  **  ALTERS:  leftExtent and rightExtent are "boiled down" from pixel units to  **  words.  The call	to ClearBufPart may	change numOfWords, currBufByte,       **  bufByte, wordCounter, and rowCounter.	                  **			                  **  NOTES: CleanUpBuffer returns with an	RTL.	                  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 4/4/86		**		******************************************;	EXPORT iCleanUpBufferiCleanUpBuffer	PROC*              using E0Vectors;	lda rightExtent	cmp leftExtent	bpl SomeExtent	bra NoExtent	;no pixel has been touched;SomeExtent		; ;note rightExtent is in acc. (measured in pixels)	lsr a	lsr a	lsr a	lsr a	sta rightExtent	;now boiled down to	words;	lda leftExtent	;in pixels	lsr a	lsr a	lsr a	lsr a	sta leftExtent	;now words;	jsl ClearBufPart;NoExtent		; ;	rtl	ENDP******************************************		**  end of CleanUpBuffer	**		******************************************;;;                copy text/textstyles******************************************		**  current date and	time:	**    4:00 PM, 5/3/86	**		******************************************;********************************************************************************			                  **              subroutine StyleText (also, StyleExtents)	                  **			                  **		started 5/2/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine subroutine modifies the text buffer to reflect  **  any current styles specified by the value of txFace.  It	also updates      **  rightExtent and leftExtent to match the new "active text	buffer" limits.   **			                  **  The subroutine has a separate entry point, StyleExtents,	which only        **  changes the extents.  This is useful	in text bounding-box calls, in which  **  only the measuring of the text extent is important	                  **			                  **  ASSUMPTIONS:  the subroutine requires qwerty qwerty qwerty qwerty qwerty   **			                  **  RETURNS:  iamozymandiaskingofkingslokuponmyworksyemightyanddespair         **			                  **  NOTES: doe a deer a female deer ray a drop of golden sun	me a name I call  **			                  * *			                  **  Modification History		                  **			                  **  19 May 86    StyleText, StyleExtents, DoBold and DoUnderline are now       **  (SEG)        E0Vectors and StyleText	has a new using E0Vectors statement.  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 5/2/8666	**		******************************************;	EXPORT iStyleTextiStyleText	PROC;*              using E0Vectors	; new using statement SEB;	stz justExtents	;style both text buffer and extents	bra DoStyle;	EXPORT iStyleExtentsiStyleExtents		;       	lda #TRUE	sta justExtents	;text buffer irrelevant;DoStyle		; 	lda txFace	beq PlainStyle;	bit #boldBit	beq NotBold;it's BOLD!	jsl DoBold	lda txFaceNotBold		; 	bit #ulineBit	beq NotUline;underline it __________ __!;	jsl DoUnderlineNotUline		; ;PlainStyle		; 	rtl	ENDP******************************************		**  end of StyleText		**  (also, StyleExtents)	**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;;;this routine fixes	a bug in DoBold and	simplifies the implementation of;the bolding algorithm.  It should be patched in instead of	DoBold in the;1.0 ROM, and should replace DoBold in the 1.1 ROM;********************************************************************************			                  **              subroutine DoBold		                  **			                  **		started 4/29/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine performs a simple bolding transformation on the **  text buffer.  The entire active chunk of the buffer is shifted 1 pixel to  **  the right, and ORed with the original buffer.  rightExtent is incremented  **  by 1 as well.			                  **			                  **  ASSUMPTIONS: to follow		                  **			                  **  NOTES: DBR is preserved.  DoBold returns with an RTL.	                  **			                  ********************************************************************************;****************************************	                  **  Feb. 5, 1987  5:00 pm              **	                  ****************************************;	EXPORT iDoBoldiDoBold	PROC;AnotherNewY	equ temp2+2;	lda rightExtent	cmp leftExtent	bpl ExtentOK	;there are some pixels to bold	rtl	;nothing to work withExtentOK		; ;****  ADDED 2/5/87 - BHM;	inc rightExtent	;saves some effort later;****  END OF ADDITION	lda justExtents	beq BoldAll	;bold text buffer and extents	rtl	;extents already bolded;BoldAll		; 	phb;	lda chHeight	sta rowCounter;;	lda leftExtent	lsr a	lsr a	lsr a	and #first15Bits	;even-byte offset to left edge	sta temp;	clc	adc bufPtr	sta tbRowPtr	lda bufPtr+2	bcc NoCarry	inc a	NoCarry	sta tbRowPtr+2;tbRowPtr now points to the low byte of	the first;word in the text buffer containing image bits;	pei tbRowPtr+1	plb	plb	;set DBR for this part of buffer;	lda rightExtent	lsr a	lsr a	lsr a	and #first15Bits	;even-byte offset to right edge;	sec	sbc temp	;get number of words spanned (* 2)	bne MoreThanAWord	brl OnlyOneWord;MoreThanAWord		; ;active text buffer	crosses word boundaries.	sta numOfBytes	;so this is >= 2;NextRow		; ;we will work from right to left along each row:	ldy numOfBytes	lda (tbRowPtr),y	;rightmost word	xba	;[IS THIS RIGHT?]	lsr a	;shift right 1 pixel	sta temp;NextWord		; 	tyx	;temp. storage	dey	dey	sty AnotherNewY	lda (tbRowPtr),y	;the word just to the left	xba	lsr a;we'll need this next time through the loop	sta temp2	lda temp;we have a carry bit still left over from the LSR	bcc RightBit0	;no bit to shift in;oh, yeah?	ora #firstBitRightBit0		; ;	txy	;y set again for rightmore word	xba	ora (tbRowPtr),y	;merge with existing buffer	sta (tbRowPtr),y;	ldy AnotherNewY	;moving left along . . .	beq LeftMostWord;	lda temp2	sta temp	;set up for next pass	bra NextWord;LeftMostWord		; ;we've gotten to the left edge of the active buffer -;no previous word to bother with	lda temp2	;already fetched and shifted	xba	ora (tbRowPtr)	sta (tbRowPtr);	dec rowCounter	beq AllDone;more rows to go - bump pointer:	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2	;on carry, inc high	word . . .	pei tbRowPtr+1	;and reset DBR	plb	plbNoCarry1		; 	bra NextRow;;****  CHANGED 2/5/87 - BHM;only-one-word case	changed to reflect already-bolded buffer;OnlyOneWord		; ;active buffer confined to one word in width;OOWNextRow		; 	lda (tbRowPtr)	xba	lsr a	xba	ora (tbRowPtr)	sta (tbRowPtr);	dec rowCounter	beq AllDone;rows to go:	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry2	inc tbRowPtr+2	pei tbRowPtr+1	plb	plbNoCarry2		; 	bra OOWNextRow;AllDone		; 	plb;	rtl	ENDP;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    2:00 PM, 5/3/86	**		******************************************;********************************************************************************			                  **              subroutine DoUnderline		                  **			                  **		started 5/3/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine adds underlining to the current image in the    **  text buffer.  The underline is put at 2 pixels below the	base line.  If    **  the font descent	is less than 2, no underlining is done.	                  **			                  **  The underlining is a "smart" one, in	which an underline pixel is skipped   **  if there is an image pixel just above, below, to the right, or to the      **  left of it.			                  **			                  **  ASSUMPTIONS:  the subroutine requires qwerty qwerty qwerty qwerty qwerty   **			                  **  RETURNS:  iamozymandiaskingofkingslokuponmyworksyemightyanddespair         **			                  **  NOTES: doe a deer a female deer ray a drop of golden sun	me a name I call  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 5/3/86		**		******************************************;	EXPORT iDoUnderlineiDoUnderline	PROC*              USING E0Vectors;descentMod	equ temp+2;	lda descent	cmp #2	beq DescentEQ2	bpl DescentGT2;descent < 2 - do not underline	rtl;DescentEQ2		; 	lda #AllBitsOff	bra GotDescentDescentGT2		; 	lda #AllBitsOnGotDescent		; 	sta DescentMod;DescentMod will be	used to zero out any garbage from below	the;underline when there is no valid image	info there;	lda rightExtent	cmp LeftExtent	bpl ExtentsOK;0 image width:	lda bufPen	cmp startBufPen;**  BUG FIX	bne NotUtterNull	;changed from "bpl";**  END OF BUG FIX - BHM  x6245;;utter null:  no image pixels, no pen change	rtl	;so what can you do?;NotUtterNull		; ;but still 0 image width	dec a	;bufPen was in acc.	sta rightExtent	lda startBufPen	sta leftExtent	bra LNROK;ExtentsOK		; 	lda bufPen	dec a	cmp rightExtent	bmi rightOK	sta rightExtentRightOK		; ;	lda startBufPen	cmp leftExtent	bpl LeftOK	sta leftExtentLeftOK		; ;leftExtent and rightExtent have now been modified to include entire underline;LNROK		; 	lda justExtents	beq UlineIt;only extents to be	changed - and they're done:	rtl;UlineIt		; 	lda leftExtent	lsr a	lsr a	lsr a	and #first15Bits	;boiled down to even-byte offset	sta temp;	PushLong #0	;for result of multiply	pei bufRowBytes	pei ascent	_Multiply	pla	;low word	clc	adc bufPtr	sta pmRowPtr	pla	adc bufPtr+2	sta pmRowPtr+2;	lda pmRowPtr	clc	adc temp	sta pmRowPtr	bcc NoCarry1	inc pmRowPtr+2NoCarry1		; ;	lda pmRowPtr	clc	adc bufRowBytes	sta tbRowPtr	lda pmRowPtr+2	bcc NoCarry2	inc a	NoCarry2	sta tbRowPtr+2	sta fontTemp+2;	lda tbRowPtr	clc	adc bufRowBytes	sta fontTemp	bcc NoCarry3	inc fontTemp+2NoCarry3		; ;;pmRowPtr now points to the first important byte in the row	above;the underline, tbRowPtr to the analogous byte in the underline's row,;and fontTemp just one row below that;	phb	pei tbRowPtr+1	;set DBR for underline's row	plb	plb;	lda rightExtent	lsr a	lsr a	lsr a	and #first15Bits	;boiled down to even byte	sec	sbc temp	;same for left bound	bne MoreThanAWord	;. . . of active text buffer	brl OnlyOneWord;MoreThanAWord		; ;acc. holds even numOfBytes, >= 2	sta numOfBytes	;added 3/10/87	tay;temp will be used to accumulate "interfering" image pixels	for the current;word; temp2 will serve the same purpose for the previous word.  Since we;need the previous word shifted to handle the current one, a lot of work can;be saved for the next pass ("previous", here, means one word to the left);	lda (tbRowPtr),y	;current word	xba	lsr a	xba	sta temp;NextWord		; ;(actually, "PreviousWord");	stz temp2	lda (tbRowPtr),y	xba	asl a	xba	ora temp	sta temp	bcc LeftBit0;left bit of current word is set - hand	it over for next pass:	lda #lastBitXBAed	sta temp2LeftBit0		; ;	lda [fontTemp],y	;word below	and descentMod	;0 if no row below,	$FFFF ow	ora [pmRowPtr],y	ora temp	sta temp;	dey	dey	lda (tbRowPtr),y	xba	lsr a	xba	ora temp2	sta temp2	bcc RightBit0;right bit of previous word set - use it here	lda #firstBitXBAed	ora temp	sta tempRightBit0		; ;	lda temp	eor #allBitsOn	iny	iny;TRY THIS, WHY DONTCHA?	ora (tbRowPtr),y;OK - CONSIDER IT TRIED	sta (tbRowPtr),y;	dey	dey	beq LeftMostWord;previous becomes current:	lda temp2	sta temp	bra NextWord;LeftMostWord		; ;new current word right-shifted and bit	from;word to the right already ORed in temp2;	lda [fontTemp]	;word below	and descentMod	;if any	ora [pmRowPtr]	;above	ora temp2	sta temp2;	lda (tbRowPtr)	xba	asl a	xba	ora temp2	eor #allBitsOn;THIS TOO	ora (tbRowPtr);GOTCHA	sta (tbRowPtr);	bra AllDone;OnlyOneWord		; ;**  ADDED 3/10/87 TO HELP WITH THE BOUNDARY PROBLEM;  (see below);	sta numOfBytes	;helps to know it's 0;**  END OF CHANGE -	BHM  x6245;	lda [fontTemp]	and descentMod	ora [pmRowPtr]	sta temp;	lda (tbRowPtr)	xba	tax	;temp. storage	lsr a	xba	ora temp	sta temp;	txa	asl a	xba	ora temp	eor #allBitsOn;AND THIS?	ora (tbRowPtr);RIGHT	sta (tbRowPtr);AllDone		; ;**  ADDED 3/10/87;formerly, the underlining was allowed to extend past the natural;boundaries of the text image being underlined to the nearest word;boundaries - we relied on BlowItUp to do the clipping.  However,;when outlining or shadowing intervene,	this cause trouble.	 Hence:;	lda leftExtent	and #last4Bits	asl a	tax	lda >leftBitMask,x	and (tbRowPtr)	;mask out the extra	on the left	sta (tbRowPtr);	lda rightExtent	and #last4Bits	asl a	tax	lda >rightBitMask,x	ldy numOfBytes	;can be 0	and (tbRowPtr),y	;mask out extra on right	sta (tbRowPtr),y;**  END OF CHANGE -	BHM  x6245;	plb	rtl	ENDP******************************************		**  end of DoUnderline	**		******************************************;                copy text/putchar******************************************		**  current date and	time:	**    4:30 PM, 4/18/86	**		******************************************;********************************************************************************			                  **              subroutine PutChar		                  **			                  **		started 4/17/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine is used to transfer character	images from the   **  font strike to the text buffer.		                  **			                  **  ASSUMPTIONS:  the subroutine requires qwerty qwerty qwerty qwerty qwerty   **			                  **  RETURNS:  iamozymandiaskingofkingslokuponmyworksyemightyanddespair         **			                  **  NOTES: doe a deer a female deer ray a drop of golden sun	me a name I call  **			                  ********************************************************************************;******************************************		**  V.0.2.0 - 4/17/86	**    A substantially different version	**    of this subroutine appeared in	**    earlier software.  Used by per-	**    mission - BHM,	4/17/86	**		******************************************;	EXPORT iPutChariPutChar	PROC*              using E0Vectors;;.......................................*imageWidth    equ temp*locTEnt       equ temp+2*startBit      equ temp2;	phb;	lda bufPen	sta imagePen	;a much-needed copy;	jsl ValidChar	tax	;temp. storage for o/w value;	and #lowByte	;get character width	clc	adc bufPen	;bump pen	sta bufPen;	lda [locTPtr],y	;this char's location table entry	MacSwitch	sta locTEnt	iny	iny	lda [locTPtr],y	;next char's entry	MacSwitch;	dec a	;our char's rightmost pixel (in FS);		;[FS = font strike]	tay	;temp. storage;	sec	sbc locTEnt	bpl Not0Width	brl ZeroWidth;Not0Width		; 	sta imageWidth	;actually, image width-1;	txa	;o/w value	xba	and #lowByte	;offset	clc	adc kernMax	clc	adc imagePen	sta imagePen	;our char's leftmost pixel (in buffer);	cmp leftExtent	;new leftmost pixel?	bpl leftFine	;no	sta leftExtent	;yesleftFine		; ;	clc	adc imageWidth	;rightmost pixel (in buffer)	cmp rightExtent	bmi rightFine	sta rightExtentRightFine		; ;thank'ee kindly, Ma'am;	lda locTEnt	;rightmost pixel in	FS	and #last4Bits;startBit is the position of the rightmost pixel (of our;character, in the font strike) within its pixelword:	sta startBit	asl a	;for access to mask	table	tax	lda >leftBitMask,x;maskLeft masks out	all the garbage in the font strike to the left of our;character's image (this "garbage" is, of course, perfectly good image;information for the previous character):	sta maskLeft;	lda locTEnt	lsr a	lsr a	lsr a	and #first15Bits;startByte is the first byte of the first font strike word containing any;pixels of our character - it is constrained to be even:	sta startByte;;pmRowPtr (pm for "pixelmap" - it's generic) points to startByte; later it;will be updated for each new row:	clc	adc strikePtr	;add startByte to font strike pointer	sta pmRowPtr	lda strikePtr+2	bcc @NoCarry1	inc a	@NoCarry1	sta pmRowPtr+2;	tya	;retrieve char's rightmost pixel in FS	and #last4Bits	;position within pixelword	asl a	tax	lda >rightBitMask,x	sta maskRight	;masks out "garbage" to the right;;now do some of the	same things for the	buffer:	lda imagePen	lsr a	lsr a	lsr a	and #first15Bits	;offset within buffer	tax	;temp. storage;;subtract bit-within-word positions (one for FS,;one for buffer) to	get shift amount	lda imagePen	and #last4Bits	sec	sbc startBit	bpl GoodShift;sinister shift - add 16 to shift amount (making it positive),;then compensate by	subtracting two bytes from the buffer offset:	clc	adc #bitsInWord	dex	;buffer offset in x	dex;GoodShift		; 	asl a	sta HowFarToShift;;tbRowPtr is to the	buffer as pmRowPtr is to the font strike:	txa	;buffer offset	clc	adc bufPtr	sta tbRowPtr	lda bufPtr+2	bcc @NoCarry2	inc a	@NoCarry2	sta tbRowPtr+2;;set DBR to match current piece of text	buffer:	pei tbRowPtr+1	plb	plb;	lda chHeight	sta rowCounter	;prepare for leap into row loop;	tya	;STILL rightmost pixel, BION	lsr a	lsr a	lsr a	and #first15Bits	;"endByte", like startByte;	sec	sbc startByte	;speaking of which . . . .;we special-case characters which do not span more than 1 font strike word:	bne MoreThanAWord	;not these	brl OnlyOneWord	;but these;;[BHMNOTE:  nice place for a file break, if needed];[BHMNOTE:  it will	be, it will be];MoreThanAWord		; ;	sta numOfBytes	;even, and here >= 2;NextRow		; ;	ldy #0;leftmost word in row:	lda [pmRowPtr]	;get font strike word	and maskLeft	;mask the garbage;no point shifting,	OR'ing, and STA'ing	a bunch of zeros:	beq NullWord;NextWord		; 	sta strikeWord	jsl ShiftStay	;rotate to match buffer	ora (tbRowPtr),y	;OR with current buffer	sta (tbRowPtr),y	;and replace;	lda strikeWord	jsl ShiftOut	;to go into next buffer word	iny	iny	ora (tbRowPtr),y	sta (tbRowPtr),y;CheckY		; ;are we down to the	last word in the row?	cpy numOfBytes	beq RightMostWord	;yes;nuhUH:	lda [pmRowPtr],y	;pick up next font strike word	bne NextWord	;if it's worth looking atNullWord		; ;it's not:	iny	;so try,	iny	;try	bra CheckY	;again;;rightmost word in a row with 2 or more	words:RightMostWord		; ;	lda [pmRowPtr],y	and maskRight	beq NullRightWord	sta strikeWord	jsl ShiftStay	ora (tbRowPtr),y	sta (tbRowPtr),y;	lda strikeWord	jsl ShiftOut	iny	iny	ora (tbRowPtr),y	sta (tbRowPtr),y;since that was the	rightmost word, we must be at the end of a row:NullRightWord		; 	dec rowCounter	beq CharDone	;end of all rows, for this char;update pointers:	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2	;pointer high word changed, so	pei tbRowPtr+1	;set new bank	plb	plbNoCarry1		; ;	lda pmRowPtr	clc	adc rowBytes	sta pmRowPtr	bcc NoCarry2	inc pmRowPtr+2NoCarry2		; 	bra NextRow;;OnlyOneWord		; ;special-case transfer for any character whose width;does not span a word boundary in the font strike;;it's like the general case, only less;	lda maskRight	and maskLeft	;merge the masks	sta maskLeft;	ldy #2;OOWNextRow		; 	lda [pmRowPtr]	and maskLeft	beq OOWNullWord;	sta strikeWord	jsl ShiftStay	ora (tbRowPtr)	sta (tbRowPtr);	lda strikeWord	jsl ShiftOut	ora (tbRowPtr),y	sta (tbRowPtr),y;OOWNullWord		; 	dec rowCounter	beq CharDone;	lda tbRowPtr	clc	adc bufRowBytes	sta tbRowPtr	bcc NoCarry3	inc tbRowPtr+2	pei tbRowPtr+1	plb	plbNoCarry3		; ;	lda pmRowPtr	clc	adc rowBytes	sta pmRowPtr	bcc NoCarry4	inc pmRowPtr+2NoCarry4		; 	bra OOWNextRow;;;ZeroWidth		; ;CharDone		; ;ain't it da truth!	plb	rtl	ENDP******************************************		**  end of PutChar		**		******************************************;                copy text/textbufcalls******************************************		**  current date and	time:	**    4:00 PM, 5/9/86	**		******************************************;********************************************************************************			                  **              subroutine SetTB		                  **			                  **		started 5/9/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  this subroutine sets the size of the text buffer.  It is 1 of 2 **  that replace SizeTextBuffer.  More documentation to follow.                **			                  **  ASSUMPTIONS:  the subroutine requires qwerty qwerty qwerty qwerty qwerty   **			                  **  RETURNS:  iamozymandiaskingofkingslokuponmyworksyemightyanddespair         **			                  **  NOTES: doe a deer a female deer ray a drop of golden sun	me a name I call  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 5/9/86		**		******************************************;	EXPORT iSetTBiSetTB	PROC*              USING E0Vectors;	lda ForcedFont	;Set or Force?	bne ForcedWidth;non-forced - apply	the default mods:	lda NewMaxFontWidth	;fontWidth	clc	adc NewMaxFontWidth	adc NewMaxFontWidth	;times 3	adc #36	;default to handle bold, italic	sta fontTemp	bra GotFontWidth;ForcedWidth		; 	lda NewMaxFontWidth	sta fontTempGotFontWidth		; ;	lda fontTemp	inc a	clc	adc maxWidth	asl a	asl a;the number in the acc. is our good-guess at the number of pixels;needed across in the font buffer - may	be changed later;	lsr a	lsr a	lsr a	and #first15bits	;in bytes	sta bufRowBytes	;useful though temp. here;	PushLong #0	;for result of mult.	pei bufRowBytes	pei newTBHeight;	_Multiply;	pei textBufHandle+2	pei textBufHandle;	_SetHandleSize;	bcc NoMemErr;memory error - carry is set, err # is in acc.:	rtl;NoMemErr		; ;;install new values:	lda NewTBHeight	sta textBufHeight	lda bufRowBytes	lsr a	sta textBufRowWords	lda ForcedFont	bne SetForced;make sure we know it's not forced:	lda #0	ldx #256	sta fontWidth,x	bra FWSet;SetForced		; 	lda newMaxFontWidth	ldx #256	sta fontWidth,x;FWSet		; ;;set up for call to	ClearBufPart:	ldx textBufHandle+2	lda textBufHandle	jsr TextDeref;	stx bufPtr+2	sta bufPtr;	stz leftExtent	lda textBufRowWords	dec a	sta rightExtent	lda textBufHeight	sta chHeight	;to fool ClearBufPart;	jsl ClearBufPart;;	clc	;no error to report	lda #0;	rtl	ENDP******************************************		**  end of SetTB		**		******************************************;;|||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||||;******************************************		**  current date and	time:	**    4:30 PM, 5/9/86	**		******************************************;********************************************************************************			                  **              subroutine ResetTB		                  **			                  **		started 5/9/86	                  **		Bennet Marks x6245	                  **			                  **  ABSTRACT:  documentation to follow		                  **			                  **  ASSUMPTIONS:  the subroutine requires qwerty qwerty qwerty qwerty qwerty   **			                  **  RETURNS:  iamozymandiaskingofkingslokuponmyworksyemightyanddespair         **			                  **  NOTES: doe a deer a female deer ray a drop of golden sun	me a name I call  **			                  ********************************************************************************;******************************************		**  V.0.1.0 - 5/9/86		**		******************************************;	EXPORT iResetTBiResetTB	PROC*              USING E0Vectors;	PushLong #0	;for multiply result;	lda newTBRowWords	asl a	sta bufRowBytes	pha;	pei NewTBHeight;	_Multiply;	pei textBufHandle+2	pei textBufHandle;	_SetHandleSize;	bcc NoMemErr;there was a mem error - carry set, number in acc.	rtl;NoMemErr		; ;;install new values:	lda NewTBHeight	sta textBufHeight	lda newTBRowWords	sta textBufRowWords	lda newFontWidth	ldx #256	sta fontWidth,x;;set up for call to	ClearBufPart:	ldx textBufHandle+2	lda textBufHandle	jsr TextDeref;	stx bufPtr+2	sta bufPtr;	stz leftExtent	lda textBufRowWords	dec a	sta rightExtent	lda textBufHeight	sta chHeight	;to fool ClearBufPart;	jsl ClearBufPart;;	clc	;no error to report	lda #0;	rtl	ENDP******************************************		**  end of ResetTB		**		******************************************;                copy text/blowitup****************************************************************** BlowItUp** This is the routine that takes the 1-bit per pixel text* image in the text	buffer and paints it to the destination* bit map as 2 or 4	bits per pixel with	the right* foreground and background color in the right text mode.** Several modes are	supported as follows**        Mode*        Code*         0    Copies foreground and background into destination*         1    OR's foreground and background with destination*         2    XOR's foreground and background with destination*         3    BIC's foreground and background with destination*         4    Copies only the foreground into the destination*	(background is untouched).*         5    OR's foreground into destination (background is*	untouched).*         6    XOR's foreground into destination (background is*	untouched).*         7    BIC's foreground into destination (background is*	untouched).** Each mode is acheived by its own handler.  The first part	of SetItUp* puts the vector to the handler in the	current JMP vector location* in bank E0.** There is no left and right mask as I rely on the MinRect to* be set up correctly.  The right MinRect means that the left* and right mask are already incorporated in the scan line* buffer.** Variables On zero	page that I use are:**     CurPMByte	 ; a pointer in the	inner loop of BlowItUp*     CurTBByte	 ; a pointer in the	inner loop of BlowItUP*     WordCounter	 ; counter in the inner loop of BlowItUp*     FG	 ; local copy of foreground color*     BG	 ; local copy of background color*     TextMode	 ; local copy of text mode** Change History** 18 Feb 87    Steven Glass** Using font flag 2	(counting from zero) we decide if we should* force the text color to be adjusted or not.  When I adjust* the color I call ExtendColorWord which copies the lowest* pixel into the other pixels of the word.  When I don't make* this call, the programmer can have dithered color text in* 640 mode or multi	colored text (a vertical striped pattern)* in any mode.*****************************************************************	EXPORT iBlowItUpiBlowItUp	PROC*              using CoreDATA*              using E0Vectors;-----------------------------------------------;; First setup the ToStuffBig vector based on the; text mode.;	ldy #o_txmode	lda [PortRef],y	sta TextMode	jsl SetStuffAdr;----------------------------------------------------------;; Check font flag 2	(numbered from zero) to see if the; programmer wants me to force the color to be right or if; s/he wants me to use the foreground and background colors; as they are passed in the port.;	stz Temp	ldy #o_FontFlags	lda [PortRef],y	and #%0000000000000100	beq NotSpecial	dec TempNotSpecial		; 	ldy #o_FGColor	lda [PortRef],y	bit Temp	bmi UseAsIs1	tax	lda PortSCB	jsr ExtendColorWordUseAsIs1	sta FG	ldy #o_BGColor	lda [PortRef],y	bit temp	bmi UseAsIs2	tax	lda PortSCB	jsr ExtendColorWordUseAsIs2	sta BG	jsl Init2Regions	lda MinRect	sta CurrentY	jsl ShieldCursor	lda TextMode	and #$7FFF	cmp #4	bcs FastBigLoop	jmp SlowBigLoop	ENDP****************************************************************** FastBigLoop** The FastBigLoop can only be used for the foreground xfer* modes.  The major	difference between fast and slow is that* in the fast loop we check each word, if it is zero, we bypass* the stuff big code.  This saves lots of time.*****************************************************************	EXPORT FastBigLoopFastBigLoop	PROC*              using CoreDATA*              using E0Vectors	lda NonRectRegions	bne BigLoop	jsl Seek2RegionsBigLoop		; 	lda NumOfWords	; set up the counters that the	sta WordCounter	; inner loop uses	lda tbStartByte	sta CurTBByte	lda pmStartByte	sta CurPMByte	lda NonRectRegions	beq SkipSeek	jsl Seek2RegionsSkipSeek		; ;------------------------------------------------------;; See which of the inner loops I should	use.;	bit TextMode	bmi InvertLoop	bit PortSCB-1	bmi Loop640Loop320		; ; this loop is for standard xfer modes	ldy CurTBByte	lda [tbRowPtr],y	; waste 2 cycles here to see if shortcut	beq NoBother320	; is available.	jsl ToStuffBig	ldy CurTBByte	iny	lda [tbRowPtr],y	iny	sty CurTBByte	jsl ToStuffBig	dec WordCounter	bpl Loop320	bra NextRowNoBother320		; 	iny	; bump y and store it for next	iny	; time around.	sty CurTBByte	lda CurPMByte	; add eight since we did not get	clc	; to go off to stuff big twice where	adc #8	; this would happen	sta CurPMByte	dec WordCounter	bpl Loop320	bra NextRowLoop640		; ; this loop is for standard xfer modes	ldy CurTBByte	lda [tbRowPtr],y	; waste 2 cycles here to see if shortcut	beq NoBother640	; is available.	jsl ToStuffBig	ldy CurTBByte	iny	lda [tbRowPtr],y	iny	sty CurTBByte	jsl ToStuffBig	dec WordCounter	bpl Loop640	bra NextRowNoBother640		; 	iny	; bump y and store it for next	iny	; time around.	sty CurTBByte	lda CurPMByte	; bump this 4 times	by moving to	inc a	; reg to speed it up	inc a	inc a	inc a	sta CurPMByte	; store it back out	dec WordCounter	bpl Loop640	bra NextRowInvertLoop		; ; this loop is for the NOT xfer modes	ldy CurTBByte	lda [tbRowPtr],y	eor #$FFFF	jsl ToStuffBig	ldy CurTBByte	iny	lda [tbRowPtr],y	eor #$FFFF	iny	sty CurTBByte	jsl ToStuffBig	dec WordCounter	bpl InvertLoopNextRow		; 	lda tbRowPtr	clc	adc BufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2NoCarry1		; 	lda pmRowPtr	clc	adc Width	sta pmRowPtr	bcc NoCarry2	inc pmRowPtr+2NoCarry2		; 	inc CurrentY	dec RowCounter	bmi AllDone	jmp BigLoopAllDone	jsl UnShieldCursor	rtl	ENDP****************************************************************** SlowBigLoop** SlowBigLoop is used when the foreground and background are* transfered.  The major difference between fast and slow is that* in the fast loop we check each word, if it is zero, we bypass* the stuff big code.  This saves lots of time.  Here we bypass* nothing.*****************************************************************	EXPORT SlowBigLoopSlowBigLoop	PROC*              using CoreDATA*              using E0VectorsBigLoop		; 	lda NumOfWords	; set up the counters that the	sta WordCounter	; inner loop uses	lda tbStartByte	sta CurTBByte	lda pmStartByte	sta CurPMByte	jsl Seek2Regions;------------------------------------------------------;; See which of the two inner loops I should use.;	bit TextMode	bmi InvertLoopLoop		; ; this loop is for standard xfer modes	ldy CurTBByte	lda [tbRowPtr],y	jsl ToStuffBig	ldy CurTBByte	iny	lda [tbRowPtr],y	iny	sty CurTBByte	jsl ToStuffBig	dec WordCounter	bpl Loop	bra NextRowInvertLoop		; ; this loop is for the NOT xfer modes	ldy CurTBByte	lda [tbRowPtr],y	eor #$FFFF	jsl ToStuffBig	ldy CurTBByte	iny	lda [tbRowPtr],y	eor #$FFFF	iny	sty CurTBByte	jsl ToStuffBig	dec WordCounter	bpl InvertLoopNextRow		; 	lda tbRowPtr	clc	adc BufRowBytes	sta tbRowPtr	bcc NoCarry1	inc tbRowPtr+2NoCarry1		; 	lda pmRowPtr	clc	adc Width	sta pmRowPtr	bcc NoCarry2	inc pmRowPtr+2NoCarry2		; 	inc CurrentY	dec RowCounter	bpl BigLoop	jsl UnShieldCursor	rtl	ENDP****************************************************************** Text640ModeTable** This is a table of jml vectors that will transfer control* back to the appropriate stuffbig routine.*****************************************************************	EXPORT Text640ModeTableText640ModeTable	PROC	jml StuffBig0640	jml StuffBig1640	jml StuffBig2640	jml StuffBig3640	jml StuffBig4640	jml StuffBig5640	jml StuffBig6640	jml StuffBig7640	ENDP****************************************************************** Text320ModeTable** This is a table of jml vectors that will transfer control* back to the appropriate stuffbig routine.*****************************************************************	EXPORT Text320ModeTableText320ModeTable	PROC	jml StuffBig0320	jml StuffBig1320	jml StuffBig2320	jml StuffBig3320	jml StuffBig4320	jml StuffBig5320	jml StuffBig6320	jml StuffBig7320	ENDP****************************************************************** SetStuffAdr*****************************************************************	EXPORT iSetStuffAdriSetStuffAdr	PROC*              using E0Vectors	bit PortSCB-1	bpl Mode320	and #$7F	asl a	asl a	tax	lda >Text640ModeTable,x	sta >ToStuffBig	lda >Text640ModeTable+2,x	sta >ToStuffBig+2	rtlMode320	and #$7F	asl a	asl a	tax	lda >Text320ModeTable,x	sta >ToStuffBig	lda >Text320ModeTable+2,x	sta >ToStuffBig+2	rtl	ENDP;                copy text/stuffbig0****************************************************************** StuffBig0** This is the routine that copies into the destination* coloring the forground and background.*****************************************************************	EXPORT StuffBig0320StuffBig0320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	sta tempFG	; this has rightly colored word	ldy CurPMByte	; get index to dest	lda [ScanMaskRef],y	; get mask for this	scan line	eor #$FFFF	; invert it	and [pmRowPtr],y	; and with orig dest	sta NotMaskAndDest	; save this here	lda [ScanMaskRef],y	; get mask back	and tempFG	; and with rightly colored word	ora NotMaskAndDest	; or with burned out dest	sta [pmRowPtr],y	; and put it back!	iny	iny	txa	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	txa	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	sta tempFG	; this has rightly colored word	lda [ScanMaskRef],y	; get mask for this	scan line	eor #$FFFF	; invert it	and [pmRowPtr],y	; and with orig dest	sta NotMaskAndDest	; save this here	lda [ScanMaskRef],y	; get mask back	and tempFG	; and with rightly colored word	ora NotMaskAndDest	; or with burned out dest	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	EXPORT StuffBig0640StuffBig0640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index*		; into conversion table	tax	lda >ConTable640,x	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	sta tempFG	; this has rightly colored word	ldy CurPMByte	; get index to dest	lda [ScanMaskRef],y	; get mask for this	scan line	eor #$FFFF	; invert it	and [pmRowPtr],y	; and with orig dest	sta NotMaskAndDest	; save this here	lda [ScanMaskRef],y	; get mask back	and tempFG	; and with rightly colored word	ora NotMaskAndDest	; or with burned out dest	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	ENDP;                copy text/stuffbig1****************************************************************** StuffBig1** This is the routine that ORs into the	destination* coloring the forground and background.*****************************************************************	EXPORT StuffBig1320StuffBig1320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; a now has rightly	colored word	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	ora [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and put it back!	iny	iny	txa	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	txa	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; this has rightly colored word	and [ScanMaskRef],y	; and with mask for	this scan line	ora [pmRowPtr],y	; or original destination	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	EXPORT StuffBig1640StuffBig1640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index*		; into conversion table	tax	lda >ConTable640,x	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; this now gives us	rightly colored word	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	ora [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	ENDP;                copy text/stuffbig2****************************************************************** StuffBig2** This is the routine that XORs into the destination with* colored forground	and background.*****************************************************************	EXPORT StuffBig2320StuffBig2320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; a now has rightly	colored word	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	eor [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and put it back!	iny	iny	txa	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	txa	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; this has rightly colored word	and [ScanMaskRef],y	; and with mask for	this scan line	eor [pmRowPtr],y	; or original destination	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	EXPORT StuffBig2640StuffBig2640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index*		; into conversion table	tax	lda >ConTable640,x	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; this now gives us	rightly colored word	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	eor [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	ENDP;                copy text/stuffbig3****************************************************************** StuffBig3** This is the routine that BICs into the destination with* colored forground	and background.*****************************************************************	EXPORT StuffBig3320StuffBig3320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; a now has rightly	colored word	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	eor #$FFFF	; BIC is not src AND dest	and [pmRowPtr],y	;	sta [pmRowPtr],y	; and put it back!	iny	iny	txa	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	txa	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; this has rightly colored word	and [ScanMaskRef],y	; and with mask for	this scan line	eor #$FFFF	; BIC is not src AND dest	and [pmRowPtr],y	;	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	EXPORT StuffBig3640StuffBig3640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index*		; into conversion table	tax	lda >ConTable640,x	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	tya	; get back orig	eor #$FFFF	; invert it	and BG	; now the background pixels are colored	ora tempFG	; this now gives us	rightly colored word	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	eor #$FFFF	; BIC is not src AND dest	and [pmRowPtr],y	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	ENDP;                copy text/stuffbig4****************************************************************** StuffBig4** This is the routine that copies only the foreground* pixels into the destination.*****************************************************************	EXPORT StuffBig4320StuffBig4320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	tay	; save copy in y	and FG	; now the foreground pixels are colored	sta TempFG	; save colored copy	here	tya	; get un colored copy back to burn*		; whole in source	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and this with mask for cur scan line	eor #$FFFF	; invert it	and [pmRowPtr],y	; and with orig dest	sta NotMaskAndDest	; save this here	lda [ScanMaskRef],y	; get mask back	and tempFG	; and with rightly colored word	ora NotMaskAndDest	; or with burned out dest	sta [pmRowPtr],y	; and put it back!	iny	iny	txa	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	txa	; get uncolored copy back to burn again	and [ScanMaskRef],y	; and with mask for	this scan line	eor #$FFFF	; invert it	and [pmRowPtr],y	; and with orig dest	sta NotMaskAndDest	; save this here	lda [ScanMaskRef],y	; get mask back	and tempFG	; and with rightly colored word	ora NotMaskAndDest	; or with burned out dest	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	EXPORT StuffBig4640StuffBig4640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index*		; into conversion table	tax	lda >ConTable640,x	tax	; save uncolored copy in x	and FG	; now the foreground pixels are colored	sta tempFG	; save it here	txa	; get uncolored copy back to burn*		; whole in src.	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask for	this scan line	eor #$FFFF	; invert it	and [pmRowPtr],y	; and with orig dest	sta NotMaskAndDest	; save this here	lda [ScanMaskRef],y	; get mask back	and tempFG	; and with rightly colored word	ora NotMaskAndDest	; or with burned out dest	sta [pmRowPtr],y	; and put it back!	iny	iny	sty CurPMByte	rtl	ENDP;                copy text/stuffbig5****************************************************************** StuffBig5** This is the routine that OR's the foreground into the dest.* It is probably the fastest of the routines.*****************************************************************	EXPORT StuffBig5320StuffBig5320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	and FG	; put color into foreground	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; clip to scan line	mask	ora [pmRowPtr],y	; or with dest	sta [pmRowPtr],y	; replace dest	iny	; now bump pointer into dest	iny	txa	; get next word from x reg	and FG	; put the color into the forground	and [ScanMaskRef],y	; mask the sucker	ora [pmRowPtr],y	; or with dest	sta [pmRowPtr],y	; store it	iny	; bump the pointer to dest while	iny	; still in reg	sty CurPMByte	; and save it.	rtl	EXPORT StuffBig5640StuffBig5640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index;		; into conversion table	tax	lda >ConTable640,x	and FG	; put color into foreground	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask	ora [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and store it	iny	; bump pointer while still in reg	iny	sty CurPMByte	; and store it	rtl	ENDP;                copy text/stuffbig6****************************************************************** StuffBig6** This is the routine that XOR's the foreground into the dest.* It is one of the fastest of the routines.*****************************************************************	EXPORT StuffBig6320StuffBig6320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	and FG	; put color into foreground	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; clip to scan line	mask	eor [pmRowPtr],y	; or with dest	sta [pmRowPtr],y	; replace dest	iny	; now bump pointer into dest	iny	txa	; get next word from x reg	and FG	; put the color into the forground	and [ScanMaskRef],y	; mask the sucker	eor [pmRowPtr],y	; or with dest	sta [pmRowPtr],y	; store it	iny	; bump the pointer to dest while	iny	; still in reg	sty CurPMByte	; and save it.	rtl	EXPORT StuffBig6640StuffBig6640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index;		; into conversion table	tax	lda >ConTable640,x	and FG	; put color into foreground	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask	eor [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and store it	iny	; bump pointer while still in reg	iny	sty CurPMByte	; and store it	rtl	ENDP;                copy text/stuffbig7****************************************************************** StuffBig7** This is the routine that BIC's the foreground into the dest.* It is not as fast	as OR and XOR but is a lot faster than* copy.*****************************************************************	EXPORT StuffBig7320StuffBig7320	PROC	and #$00FF	; deal with only one byte at a time	asl a	; quadruple the value so can index	asl a	; into conversion table	tax	lda >ConTable320+2,x	tay	lda >ConTable320,x	tyx	and FG	; put color into foreground	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; clip to scan line	mask	eor #$FFFF	and [pmRowPtr],y	; or with dest	sta [pmRowPtr],y	; replace dest	iny	; now bump pointer into dest	iny	txa	; get next word from x reg	and FG	; put the color into the forground	and [ScanMaskRef],y	; mask the sucker	eor #$FFFF	and [pmRowPtr],y	; or with dest	sta [pmRowPtr],y	; store it	iny	; bump the pointer to dest while	iny	; still in reg	sty CurPMByte	; and save it.	rtl	EXPORT StuffBig7640StuffBig7640		;       	and #$00FF	; deal with only one byte at a time	asl a	; double the value so can index;		; into conversion table	tax	lda >ConTable640,x	and FG	; put color into foreground	ldy CurPMByte	; get index to dest	and [ScanMaskRef],y	; and with mask	eor #$FFFF	and [pmRowPtr],y	; or with orig dest	sta [pmRowPtr],y	; and store it	iny	; bump pointer while still in reg	iny	sty CurPMByte	; and store it	rtl	ENDP	END